/* =========================
   LISTA DE ORDENS - SUPORTE
   lista-ordens.css (Versão com Scroll Horizontal)
   ========================= */

/* =========================
   CONTAINER E SCROLL
   ========================= */
.orders-container {
    background: #fff;
    padding: 1.5rem;
    border-radius: 10px;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    margin-top: 1.5rem;
    /* Propriedades vitais para o scroll horizontal */
    width: 100%;
    overflow-x: auto; /* Cria a barra de rolagem automaticamente */
    -webkit-overflow-scrolling: touch; /* Scroll suave no iOS */
    position: relative;
}

/* Estilização da Barra de Rolagem (Scrollbar) */
.orders-container::-webkit-scrollbar {
    height: 10px; /* Altura da barra horizontal */
}

.orders-container::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 5px;
}

.orders-container::-webkit-scrollbar-thumb {
    background: #c1c1c1; /* Cor da barra */
    border-radius: 5px;
    border: 2px solid #f1f1f1;
}

.orders-container::-webkit-scrollbar-thumb:hover {
    background: var(--secondary); /* Cor ao passar o mouse */
}

/* =========================
   TABELA
   ========================= */
.orders-table {
    width: 100%;
    border-collapse: collapse;
    /* Define uma largura mínima para FORÇAR o scroll em telas pequenas */
    min-width: 1000px; 
}

.orders-table th, 
.orders-table td {
    padding: 1rem 1.2rem;
    text-align: left;
    border-bottom: 1px solid var(--border-light);
    font-size: 0.9rem;
    vertical-align: middle;
    white-space: nowrap; /* Impede que o texto quebre linha, mantendo a tabela larga */
}

.orders-table th {
    background: #f8f9fa;
    color: var(--text-dark);
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 0.5px;
    position: sticky; /* Opcional: mantem o header fixo se houver scroll vertical */
    top: 0;
}

.orders-table tbody tr {
    transition: background-color 0.2s;
}

.orders-table tbody tr:hover {
    background-color: #f0f7ff; /* Destaque leve ao passar o mouse */
}

/* Coluna Código */
.orders-table td:nth-child(1) {
    font-weight: 700;
    color: var(--primary-dark);
}

/* =========================
   STATUS (BADGES)
   ========================= */
.status {
    padding: 0.4rem 0.8rem;
    border-radius: 50px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    justify-content: center;
    min-width: 100px; /* Garante tamanho uniforme */
}

.status.pendente { background: rgba(255,152,0,0.1); color: #e68900; border: 1px solid rgba(255,152,0,0.2); }
.status.em-andamento { background: rgba(33,150,243,0.1); color: #0b7ad1; border: 1px solid rgba(33,150,243,0.2); }
.status.concluída, .status.concluida { background: rgba(76,175,80,0.1); color: #2e7d32; border: 1px solid rgba(76,175,80,0.2); }
.status.nao-concluida { background: rgba(244, 67, 54, 0.1); color: #c62828; border: 1px solid rgba(244, 67, 54, 0.2); }

/* =========================
   AÇÕES (BOTÕES)
   ========================= */
.actions {
    display: flex;
    gap: 0.5rem;
}

.actions button, .actions .disabled {
    border: none;
    padding: 0.5rem 0.8rem;
    border-radius: 6px;
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    transition: all 0.2s;
}

/* Botão Ver */
.view-btn { 
    background: #fff; 
    border: 1px solid #d1d5db; 
    color: var(--text-medium); 
}
.view-btn:hover { border-color: var(--secondary); color: var(--secondary); }

/* Botão Assumir */
.btn-assumir { 
    background: rgba(122,4,235,0.1); 
    color: var(--secondary); 
}
.btn-assumir:hover { background: var(--secondary); color: white; }

/* Botão Finalizar */
.btn-encerrar { 
    background: rgba(76,175,80,0.1); 
    color: #2e7d32; 
}
.btn-encerrar:hover { background: #2e7d32; color: white; }

/* Botão Desabilitado */
.disabled {
    background: #f3f4f6;
    color: #9ca3af;
    cursor: not-allowed;
    border: 1px solid transparent;
}

/* =========================
   MODAIS E POPUPS
   ========================= */
.modal, .popup {
    display: none;
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(16, 23, 40, 0.7);
    z-index: 2000;
    backdrop-filter: blur(4px);
    justify-content: center;
    align-items: center;
    padding: 1rem; /* Espaço lateral no mobile */
}

/* Animação suave */
.modal-content, .popup-content {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    width: 100%;
    max-width: 600px;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 20px 50px rgba(0,0,0,0.3);
    position: relative;
    animation: zoomIn 0.2s ease-out;
}

@keyframes zoomIn {
    from { transform: scale(0.95); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.5rem;
    border-bottom: 1px solid var(--border-light);
    padding-bottom: 1rem;
}

.modal-header h3, .popup-content h3 {
    font-size: 1.3rem;
    color: var(--primary-dark);
    margin: 0;
}

.modal-close {
    font-size: 1.8rem;
    cursor: pointer;
    color: #999;
    line-height: 1;
}

/* Campos de Texto no Popup */
.popup-content textarea {
    width: 100%;
    height: 120px;
    padding: 1rem;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    margin: 1rem 0 1.5rem 0;
    resize: none;
    font-family: inherit;
    font-size: 0.95rem;
}

.popup-content textarea:focus {
    outline: none;
    border-color: var(--secondary);
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

.popup-buttons {
    display: flex;
    gap: 1rem;
    justify-content: flex-end;
}

/* Anexos no Modal */
.detail-section {
    margin-top: 1.5rem;
    border-top: 1px solid var(--border-light);
    padding-top: 1rem;
}

.anexos-container {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 1rem;
    margin-top: 1rem;
}

.anexo-item {
    border: 1px solid var(--border-light);
    border-radius: 8px;
    padding: 0.5rem;
    text-align: center;
    background: #f9f9f9;
}

.anexo-imagem {
    width: 100%;
    height: 100px;
    object-fit: cover;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

.anexo-link {
    font-size: 0.8rem;
    color: var(--secondary);
    text-decoration: none;
    display: block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* =========================
   RESPONSIVIDADE (Correções Finais)
   ========================= */

@media (max-width: 768px) {
    .orders-container {
        padding: 1rem;
        margin-top: 1rem;
        /* Assegura que a barra apareça */
        overflow-x: scroll; 
    }

    /* Garante que a tabela não encolha e force o scroll */
    .orders-table {
        min-width: 900px; /* Ajuste conforme a quantidade de colunas */
    }

    /* Aumenta a área de toque dos botões no mobile */
    .actions button {
        padding: 0.6rem 1rem;
    }

    /* Ajuste nos modais para ocupar mais tela no mobile */
    .modal-content, .popup-content {
        width: 95%;
        padding: 1.5rem;
        margin: auto;
    }

    .popup-buttons {
        flex-direction: column; /* Botões empilhados no popup */
    }

    .popup-buttons button {
        width: 100%;
        padding: 0.8rem;
    }
}

main/front-end/assets/css/termos.css.content:
/* =======================
   Termos de Serviço - OTIMIZADO
   ======================= */

/* Container Principal */

/* Botão de fechar */
.close-btn {
    font-size: 1.5rem;
    color: var(--text-light);
    text-decoration: none; 
    background: transparent;
    border: none;
    cursor: pointer;
    transition: transform 0.2s, color 0.2s;
}

.close-btn:hover {
    color: var(--accent);
    transform: scale(1.2);
}

.termos-container {
    display: flex;
    justify-content: center;
    padding: clamp(1rem, 4vw, 2rem);
    min-height: calc(100vh - 140px);
    align-items: flex-start;
}

.termos-content {
    max-width: 900px;
    width: 100%;
    background: rgba(16, 23, 40, 0.9);
    backdrop-filter: blur(15px);
    border-radius: 20px;
    padding: clamp(1.5rem, 4vw, 2.5rem);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.15);
}

/* Área Scrollable - MELHORADA */
.termos-scrollable {
    max-height: 65vh;
    overflow-y: auto;
    padding-right: 1rem;
    scroll-behavior: smooth;
}

/* Scrollbar personalizada - COMPATÍVEL */
.termos-scrollable::-webkit-scrollbar {
    width: 6px;
}

.termos-scrollable::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 10px;
}

.termos-scrollable::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, var(--secondary) 0%, var(--accent) 100%);
    border-radius: 10px;
}

.termos-scrollable::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, var(--accent) 0%, var(--secondary) 100%);
}

/* Firefox */
.termos-scrollable {
    scrollbar-width: thin;
    scrollbar-color: var(--secondary) rgba(255, 255, 255, 0.05);
}

/* Título - RESPONSIVO */
.termos-title {
    font-size: clamp(1.8rem, 5vw, 2.5rem);
    font-weight: 700;
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    margin-bottom: 1.5rem;
    text-align: center;
    position: relative;
    padding-bottom: 1rem;
    line-height: 1.2;
}

.termos-title::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 25%;
    width: 50%;
    height: 3px;
    background: var(--gradient);
    border-radius: 3px;
}

.termos-intro {
    font-size: clamp(1rem, 2.5vw, 1.1rem);
    line-height: 1.6;
    margin-bottom: 2rem;
    color: rgba(255, 255, 255, 0.9);
    text-align: center;
    font-weight: 500;
}

/* Cabeçalhos - RESPONSIVOS */
h2 {
    font-size: clamp(1.2rem, 3vw, 1.5rem);
    color: var(--text-light);
    margin-top: 2rem;
    margin-bottom: 1rem;
    position: relative;
    padding-left: 1.5rem;
    font-weight: 600;
    line-height: 1.3;
}

h2::before {
    content: '•';
    color: var(--accent);
    position: absolute;
    left: 0;
    font-size: 1.8rem;
    line-height: 1;
    font-weight: bold;
}

/* Parágrafos - OTIMIZADOS */
.termos-content p {
    font-size: clamp(0.9rem, 2vw, 1rem);
    line-height: 1.7;
    margin-bottom: 1.25rem;
    color: rgba(255, 255, 255, 0.85);
    text-align: justify;
}

.termos-content p:last-of-type {
    margin-bottom: 0;
}

.termos-update {
    font-style: italic;
    text-align: right;
    margin-top: 2.5rem;
    color: rgba(255, 255, 255, 0.7);
    font-size: 0.9rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding-top: 1rem;
}

/* =======================
   Responsividade Avançada
   ======================= */
@media (max-width: 768px) {
    .termos-container {
        padding: 1rem;
        min-height: calc(100vh - 120px);
    }

    .termos-scrollable {
        max-height: 60vh;
        padding-right: 0.5rem;
    }

    h2 {
        padding-left: 1.25rem;
        margin-top: 1.75rem;
    }

    .termos-title::after {
        left: 20%;
        width: 60%;
    }
}

@media (max-width: 480px) {
    .termos-container {
        padding: 0.75rem;
    }

    .termos-content {
        padding: 1.25rem;
        border-radius: 15px;
    }

    .termos-scrollable {
        max-height: 55vh;
    }

    h2 {
        padding-left: 1rem;
        font-size: 1.1rem;
    }

    h2::before {
        left: -0.25rem;
        font-size: 1.5rem;
    }

    .termos-content p {
        text-align: left; /* Melhor legibilidade em mobile */
        line-height: 1.6;
    }

    .termos-title::after {
        left: 15%;
        width: 70%;
    }

    .termos-update {
        text-align: center;
        margin-top: 2rem;
    }
}

@media (max-width: 360px) {
    .termos-content {
        padding: 1rem;
    }

    .termos-title {
        font-size: 1.6rem;
    }

    h2 {
        font-size: 1rem;
        padding-left: 0.75rem;
    }
}

/* Melhorias de Acessibilidade */
@media (prefers-reduced-motion: reduce) {
    .termos-scrollable {
        scroll-behavior: auto;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
    .termos-content {
        background: var(--primary-dark);
        border: 2px solid var(--text-light);
    }

    .termos-content p {
        color: var(--text-light);
    }
}

