    margin-bottom: var(--spacing-medium);
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    line-height: 1.2;
}

.subtitle {
    font-size: clamp(1rem, 4vw, 1.125rem);
    margin-bottom: var(--spacing-large);
    color: rgba(255, 255, 255, 0.9);
    line-height: 1.5;
    padding: 0 var(--spacing-small);
}

/* Container do botão posicionado na parte inferior */
.btn-container {
    margin-top: auto; /* Empurra o botão para baixo */
    margin-bottom: var(--spacing-large);
    padding: var(--spacing-medium) 0;
}

/* Botão Login - POSICIONADO ABAIXO */
.btn-login {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 1rem 2.5rem;
    background: var(--gradient);
    color: var(--text-light);
    border-radius: 50px;
    text-decoration: none;
    font-weight: 600;
    transition: all 0.3s ease;
    border: none;
    cursor: pointer;
    font-size: 1.1rem;
    box-shadow: 0 4px 15px rgba(122, 4, 235, 0.3);
}

.btn-login .arrow {
    transition: transform 0.3s;
}

.btn-login:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 25px rgba(122, 4, 235, 0.4);
}

.btn-login:hover .arrow {
    transform: translateX(4px);
}

/* =======================
   Navbar - COMPACTO
   ======================= */
.navbar {
    background: var(--primary);
    padding: 1rem var(--spacing-medium);
    position: relative;
    z-index: 100;
    flex-shrink: 0; /* Não encolhe */
}

.nav-container {
    display: flex;
    justify-content: center;
    align-items: center;
}

.logo-container {
    display: flex;
    align-items: center;
    gap: 12px;
}

.logo {
    height: 35px;
    width: auto;
}

.logo-text {
    color: var(--text-light);
    font-weight: bold;
    font-size: var(--font-size-large);
    white-space: nowrap;
}

/* =======================
   Footer - SEMPRE VISÍVEL
   ======================= */
.footer {
    background: var(--primary-dark);
    padding: 1rem var(--spacing-medium);
    text-align: center;
    flex-shrink: 0; /* Não encolhe */
    width: 100%;
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
}

.footer-links {
    margin-top: 0.5rem;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-small);
}

.footer-link {
    color: var(--text-light);
    text-decoration: none;
    transition: color 0.3s;
    font-size: 0.9rem;
}

.footer-link:hover {
    color: var(--accent);
}

.divider {
    color: rgba(255, 255, 255, 0.3);
}

/* =======================
   Estrutura do Body - SEM SCROLL
   ======================= */
body {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    overflow: hidden; /* Remove scroll global */
}

main {
    flex: 1;
    display: flex;
    flex-direction: column;
}

/* =======================
   Responsividade
   ======================= */
@media (max-width: 768px) {
    .hero {
        padding: 0 var(--spacing-small);
        height: 100vh; /* Mantém 100% viewport */
    }
    
    .hero-content {
        padding: 1rem 0;
    }
    
    .hero h1 {
        font-size: 2.5rem;
        margin-bottom: 1rem;
    }
    
    .subtitle {
        font-size: 1.1rem;
        margin-bottom: 2rem;
    }
    
    .btn-login {
        padding: 1rem 2rem;
        font-size: 1rem;
    }
    
    .btn-container {
        margin-bottom: var(--spacing-medium);
    }
    
    .footer {
        padding: 0.75rem var(--spacing-small);
    }
}

@media (max-width: 480px) {
    .hero h1 {
        font-size: 2rem;
    }
    
    .subtitle {
        font-size: 1rem;
        padding: 0;
    }
    
    .btn-login {
        padding: 0.875rem 1.75rem;
        font-size: 0.95rem;
    }
    
    .footer-links {
        flex-direction: column;
        gap: 0.5rem;
    }
    
    .divider {
        display: none;
    }
    
    .navbar {
        padding: 0.75rem var(--spacing-small);
    }
    
    .logo-text {
        font-size: 1.1rem;
    }
    
    .logo {
        height: 30px;
    }
}

/* Para telas muito altas */
@media (min-height: 900px) {
    .hero-content {
        padding: 3rem 0;
    }
    
    .btn-container {
        margin-bottom: 3rem;
    }
}

/* Para telas muito baixas */
@media (max-height: 600px) {
    .hero-content {
        padding: 1rem 0;
    }
    
    .hero h1 {
        font-size: 2rem;
        margin-bottom: 0.5rem;
    }
    
    .subtitle {
        margin-bottom: 1rem;
        font-size: 0.9rem;
    }
    
    .btn-container {
        margin-bottom: 1rem;
    }
    
    .footer {
        padding: 0.5rem var(--spacing-small);
    }
}

main/front-end/assets/css/transferir-pod.content:
/* =======================
   Transferir Poder - Admin
   ======================= */

.page-header {
    margin-bottom: 2rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid var(--border-light);
}

.page-header h1 {
    font-size: 2rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 0.5rem;
}

.page-header h1 i {
    color: var(--secondary);
}

.page-header p {
    color: var(--text-medium);
    font-size: 1.1rem;
}

/* =======================
   Seção de Transferência
   ======================= */

.transfer-section {
    margin-bottom: 3rem;
}

.transfer-card {
    background: white;
    border-radius: 10px;
    padding: 2rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
}

.transfer-card h3 {
    font-size: 1.4rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--border-light);
}

/* Formulário */
.form-group {
    margin-bottom: 1.5rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: var(--primary-dark);
}

.form-group select,
.form-group input[type="date"] {
    width: 100%;
    padding: 0.8rem 1rem;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    font-size: 0.95rem;
    transition: all 0.3s;
}

.form-group select:focus,
.form-group input[type="date"]:focus {
    outline: none;
    border-color: var(--secondary);
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

/* Radio Buttons Personalizados */
.radio-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-weight: 500;
    color: var(--text-dark);
    transition: color 0.3s;
}

.radio-label:hover {
    color: var(--secondary);
}

.radio-label input[type="radio"] {
    display: none;
}

.radio-custom {
    width: 20px;
    height: 20px;
    border: 2px solid var(--border-light);
    border-radius: 50%;
    position: relative;
    transition: all 0.3s;
}

.radio-label input[type="radio"]:checked + .radio-custom {
    border-color: var(--secondary);
    background: var(--secondary);
}

.radio-label input[type="radio"]:checked + .radio-custom::after {
    content: '';
    width: 8px;
    height: 8px;
    background: white;
    border-radius: 50%;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* Informações */
.transfer-info {
    background: #f8f9fa;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1.5rem;
}

.info-item {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    margin-bottom: 0.75rem;
    font-size: 0.9rem;
    color: var(--text-medium);
}

.info-item:last-child {
    margin-bottom: 0;
}

.info-item i {
    color: var(--secondary);
    margin-top: 0.1rem;
    flex-shrink: 0;
}

.info-item strong {
    color: var(--primary-dark);
}

/* =======================
   Histórico
   ======================= */

.history-section {
    background: white;
    border-radius: 10px;
    padding: 2rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
}

.section-header {
    margin-bottom: 1.5rem;
}

.section-header h3 {
    font-size: 1.3rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin: 0;
}

/* Tabela */
.transfers-table {
    width: 100%;
    border-collapse: collapse;
}

.transfers-table th {
    background: #f8f9fa;
    padding: 1rem;
    text-align: left;
    font-weight: 600;
    color: var(--primary-dark);
    border-bottom: 1px solid var(--border-light);
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.transfers-table td {
    padding: 1rem;
    border-bottom: 1px solid var(--border-light);
    font-size: 0.95rem;
}

.transfers-table tbody tr {
    transition: all 0.3s;
}

.transfers-table tbody tr:hover {
    background: #f8f9fa;
}

.transfers-table tbody tr:last-child td {
    border-bottom: none;
}

/* Status */
.status-badge {
    padding: 0.4rem 0.8rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}

.status-badge.active {
    background: rgba(76, 175, 80, 0.1);
    color: #4CAF50;
}

.status-badge.expired {
    background: rgba(244, 67, 54, 0.1);
    color: #F44336;
}

.status-badge.pending {
    background: rgba(255, 152, 0, 0.1);
    color: #FF9800;
}

/* Ações */
.actions-cell {
    display: flex;
    gap: 0.5rem;
}

.btn-table {
    padding: 0.5rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.btn-table.revoke {
    background: rgba(244, 67, 54, 0.1);
    color: #F44336;
}

.btn-table:hover {
    transform: scale(1.1);
}

.btn-table.revoke:hover {
    background: #F44336;
    color: white;
}

/* =======================
   Botões - PADRONIZADO
   ======================= */

.btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    border: none;
    font-size: 0.95rem;
}

.btn-primary {
    background: var(--secondary);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.btn-primary:disabled {
    background: var(--text-light);
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

/* =======================
   Responsividade
   ======================= */

@media (max-width: 768px) {
    .transfer-card {
        padding: 1.5rem;
    }

    .radio-group {
        flex-direction: column;
    }

    .transfers-table {
        font-size: 0.85rem;
    }

    .transfers-table th,
    .transfers-table td {
        padding: 0.8rem 0.5rem;
    }

    .actions-cell {
        flex-direction: column;
    }

    .btn-table {
        width: 100%;
    }
}

@media (max-width: 576px) {
    .history-section {
        padding: 1.5rem;
    }

    .btn {
        width: 100%;
        justify-content: center;
    }
}

main/front-end/assets/css/global.css.content:
/* =======================
   global.css
   ======================= */
/* =======================
   Variáveis Globais
   ======================= */
:root {
    --primary-dark: #0a101f;
    --primary: #101728;
    --secondary: #7a04eb;
    --accent: #ff00e2;
    --text-light: #ffffff;
    --gradient: linear-gradient(90deg, var(--secondary) 0%, var(--accent) 100%);
    --font-size-large: 1.5rem;
    --font-size-medium: 1rem;
    --font-size-small: 0.875rem;
    --spacing-small: 0.5rem;
    --spacing-medium: 1rem;
    --spacing-large: 2rem;
}


/* =======================
   Reset e Configurações Gerais
   ======================= */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', system-ui, sans-serif;
}
html {
    scroll-behavior: smooth;
}
body {
    background-color: var(--primary);
    color: var(--text-light);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    overflow-x: hidden;
}
    /* =======================
    Estrutura Professor Dashboard
    ======================= */
.professor-dashboard {
    display: flex;
    min-height: 100vh;
}

/* Navbar Superior */

.navbar {
    background: var(--primary);
    padding: var(--spacing-large) var(--spacing-medium);
    display: flex;
    justify-content: center;
    position: relative;
    z-index: 100;
}

.nav-container {
    width: 100%;
    max-width: 1200px;
}

.logo-link {
    text-decoration: none;
    display: flex;
    justify-content: center;
}

.logo-container {
    display: flex;
    align-items: center;
    gap: 0;
    transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    position: relative;
}

.logo-container:hover {
    gap: 15px;
    transform: translateX(-20px);
}

.logo {
    height: 40px;
    transition: transform 0.3s;
}

.logo-container:hover .logo {
    transform: scale(1.1);
}

.logo-text {
    color: var(--text-light);
    font-weight: bold;
    font-size: var(--font-size-large);
    opacity: 0;
    width: 0;
    overflow: hidden;
    transition: all 0.4s ease;
    white-space: nowrap;
}

.logo-container:hover .logo-text {
    opacity: 1;
    width: auto;
    padding-right: var(--spacing-small);
}

@media (max-width: 768px) {
    .navbar {
        padding: var(--spacing-medium);
    }
    .logo-container {
        flex-direction: column;
    }
}

.user-profile {
    display: flex;
    align-items: center;
    gap: 1rem;
    position: relative;
}

.profile-info {
    text-align: right;
}

.user-name {
    display: block;
    font-weight: 600;
}

.user-email {
    display: block;
    font-size: 0.8rem;
    opacity: 0.8;
}

.profile-avatar {
    width: 40px;
    height: 40px;
    cursor: pointer;
    border: 2px solid var(--secondary);
    border-radius: 50% !important;
}

.user-profile img,
.profile-dropdown img {
    border-radius: 50% !important;
    object-fit: cover !important;
}

.profile-dropdown {
    position: relative;
}

.dropdown-content {
    position: absolute;
    top: 100%;
    right: 0;
    background: var(--primary-dark);
    border-radius: 8px;
    padding: 0.5rem;
    min-width: 150px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    display: none;
}

.dropdown-content a {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-light);
    text-decoration: none;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    transition: background 0.3s;
}

.dropdown-content a:hover {
    background: var(--secondary);
}

.profile-dropdown:hover .dropdown-content {
    display: block;
}

/* Menu Lateral */
.sidebar {
    background: var(--primary-dark);
    width: 250px;
    position: fixed;
    top: 80px;
    left: 0;
    bottom: 0;
    padding: 1.5rem 0;
    z-index: 900;
}

.sidebar-nav ul {
    list-style: none;
}

.sidebar-nav a {
    display: flex;
    align-items: center;
    gap: 1rem;
    color: var(--text-light);
    text-decoration: none;
    padding: 1rem 1.5rem;
    transition: all 0.3s;
    border-left: 4px solid transparent;
}

.sidebar-nav a:hover,
.sidebar-nav a.active {
    background: rgba(122, 4, 235, 0.1);
    border-left-color: var(--secondary);
    color: var(--accent);
}

.sidebar-nav i {
    width: 20px;
    text-align: center;
}

/* Conteúdo Principal */

.order-header {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 2rem;
}

.back-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-light);
    text-decoration: none;
    padding: 0.5rem 1rem;
    border-radius: 6px;
    background: var(--primary-dark);
    transition: all 0.3s;
}

.back-link:hover {
    background: var(--secondary);
    color: var(--text-light);
    transform: translateX(-5px);
}

.order-header h1 {
    font-size: 2rem;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}


    /* =======================
    Footer
    ======================= */
.footer {
    position: relative;
    margin-top: auto;
}

.footer-content {
    position: relative;
    z-index: 2;
    text-align: center;
    padding: var(--spacing-large) 0;
    background-color: var(--primary-dark);
}
    /* =======================
    Footer
    ======================= */
.footer {
    background: var(--primary-dark);
    padding: var(--spacing-medium) 0;
    text-align: center;
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
}

.footer-links {
    margin-top: var(--spacing-small);
}

.footer-link {
    color: var(--text-light);
    text-decoration: none;
    transition: all 0.3s;
    position: relative;
}

.footer-link:hover {
    color: var(--accent);
}

.footer-link:hover::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 100%;
    height: 2px;
    background: var(--gradient);
}

.divider {
    margin: 0 var(--spacing-small);
    color: rgba(255, 255, 255, 0.3);
}

    /* =======================
    Acessibilidade
    ======================= */
a:focus, button:focus {
    outline: 2px solid var(--accent);
    outline-offset: 4px;
}

    /* =======================
    Responsividade
    ======================= */
@media (max-width: 1200px) {
    .hero {
        padding: var(--spacing-large);
    }
}

@media (max-width: 992px) {
    .hero {
        flex-direction: column;
        text-align: center;
        gap: var(--spacing-large);
        padding-top: 4rem;
    }

    .hero-content {
        padding-right: 0;
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .subtitle {
        max-width: 100%;
    }

    .btn-login {
        padding: 0.8rem 2rem;
    }
}

@media (max-width: 576px) {
    .hero h1 {
        font-size: 2.5rem;
    }

    .subtitle {
        font-size: var(--font-size-small);
    }

    .btn-login {
        padding: var(--spacing-small) var(--spacing-medium);
    }

    .logo-text {
        display: none;
    }

    .logo-container:hover {
        transform: translateX(0);
        gap: 0;
    }
        .logo-text {
        display: block !important; /* Garante que o texto aparece */
    }
    
    .logo-container:hover {
        transform: none; /* Remove transform em mobile */
        gap: 8px; /* Mantém gap consistente */
    }
    
    /* Garante que o body tenha scroll quando necessário */
    html, body {
        overflow-x: hidden;
        overflow-y: auto;
        height: auto;
        min-height: 100vh;
    }
}

