    gap: 5px;
}

.status-badge.valid { background: rgba(76, 175, 80, 0.1); color: var(--success); }
.status-badge.invalid { background: rgba(244, 67, 54, 0.1); color: var(--danger); }

/* =======================
   Histórico
   ======================= */

.history-section {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
}

.history-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.history-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1.2rem;
    background: #f8f9fa;
    border-radius: 10px;
    transition: all 0.3s;
    border: 1px solid transparent;
}

.history-item:hover {
    background: white;
    border-color: var(--border-light);
    box-shadow: 0 5px 15px rgba(0,0,0,0.05);
    transform: translateX(5px);
}

.history-icon {
    width: 45px;
    height: 45px;
    border-radius: 10px;
    background: rgba(122, 4, 235, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--secondary);
    font-size: 1.1rem;
    flex-shrink: 0;
}

.history-content {
    flex: 1;
}

.history-content p {
    margin: 0 0 0.3rem 0;
    color: var(--primary-dark);
    font-weight: 600;
}

.history-time {
    color: var(--text-light);
    font-size: 0.85rem;
}

.history-stats {
    display: flex;
    gap: 1.5rem;
    font-size: 0.9rem;
    color: var(--text-medium);
}

.history-stats span {
    display: flex;
    align-items: center;
    gap: 6px;
}

/* =======================
   ALERTAS CUSTOMIZADOS (Faltava no original)
   ======================= */

.alert-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(16, 23, 40, 0.7); /* Backdrop escuro */
    backdrop-filter: blur(4px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 10000;
    opacity: 0;
    transition: opacity 0.3s ease;
    visibility: hidden;
}

.alert-overlay.visible {
    opacity: 1;
    visibility: visible;
}

.alert-modal {
    background: white;
    padding: 2rem;
    border-radius: 16px;
    max-width: 450px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    text-align: center;
    transform: translateY(20px);
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.alert-overlay.visible .alert-modal {
    transform: translateY(0);
}

.alert-icon {
    width: 70px;
    height: 70px;
    margin: 0 auto 1.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
}

/* Cores dos Ícones de Alerta */
.alert-success .alert-icon { background: rgba(76, 175, 80, 0.1); color: var(--success); }
.alert-error .alert-icon { background: rgba(244, 67, 54, 0.1); color: var(--danger); }
.alert-warning .alert-icon { background: rgba(255, 152, 0, 0.1); color: var(--warning); }
.alert-info .alert-icon { background: rgba(33, 150, 243, 0.1); color: var(--info); }

.alert-title {
    font-size: 1.4rem;
    color: var(--primary-dark);
    margin-bottom: 0.8rem;
    font-weight: 700;
}

.alert-message {
    color: var(--text-medium);
    font-size: 1rem;
    line-height: 1.5;
    margin-bottom: 2rem;
}

.alert-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.alert-btn {
    padding: 0.8rem 2rem;
    border-radius: 8px;
    border: none;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    font-size: 0.95rem;
    min-width: 120px;
}

.alert-btn-primary { background: var(--secondary); color: white; }
.alert-btn-primary:hover { background: var(--accent); box-shadow: 0 4px 15px rgba(122, 4, 235, 0.3); }

.alert-btn-secondary { background: #f0f2f5; color: var(--text-medium); }
.alert-btn-secondary:hover { background: #e1e5eb; color: var(--text-dark); }

/* =======================
   Botões Padronizados
   ======================= */

.btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    border: none;
    font-size: 0.95rem;
    min-height: 44px;
}

.btn-primary {
    background: var(--secondary);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.btn-primary:disabled {
    background: #ccc;
    cursor: not-allowed;
    transform: none;
}

.btn-secondary {
    background: #f0f2f5;
    color: var(--text-dark);
}

.btn-secondary:hover {
    background: #e6e9f0;
    transform: translateY(-1px);
}

/* =======================
   Responsividade
   ======================= */

@media (max-width: 768px) {
    .page-header h1 { font-size: 1.6rem; }

    .upload-area {
        padding: 2rem 1rem;
    }

    .upload-info {
        flex-direction: column;
        text-align: center;
    }

    .preview-stats {
        grid-template-columns: repeat(2, 1fr);
        gap: 1rem;
    }

    .table-header {
        flex-direction: column;
        gap: 1rem;
        align-items: flex-start;
    }

    .table-actions {
        width: 100%;
        flex-direction: column;
    }

    .table-actions .btn {
        width: 100%;
    }

    /* Tabela Mobile - Otimização */
    .preview-table th:nth-child(3), 
    .preview-table td:nth-child(3) { /* Email */
        display: none;
    }

    .preview-table th, .preview-table td {
        padding: 0.8rem 0.5rem;
        font-size: 0.85rem;
    }
}

@media (max-width: 576px) {
    .upload-card {
        padding: 1.5rem;
    }

    .preview-stats {
        grid-template-columns: 1fr;
    }

    .history-item {
        flex-direction: column;
        align-items: flex-start;
        gap: 0.8rem;
    }

    .history-stats {
        flex-direction: column;
        gap: 0.5rem;
        width: 100%;
    }

    /* Ajuste de Alertas */
    .alert-modal {
        padding: 1.5rem;
    }

    .alert-actions {
        flex-direction: column;
    }

    .alert-btn {
        width: 100%;
    }
}

main/front-end/assets/css/login.css.content:
/* =======================
   Login - RESPONSIVO
   ======================= */
/* Container Principal */
.auth-container {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: calc(100vh - 140px);
    padding: clamp(1rem, 4vw, 2rem);
    background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 100%);
}

/* Card de Autenticação - RESPONSIVO */
.auth-card {
    width: 100%;
    max-width: min(500px, 90vw);
    background: rgba(16, 23, 40, 0.95);
    backdrop-filter: blur(15px);
    border-radius: 20px;
    padding: clamp(1.5rem, 5vw, 3rem);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.15);
    transform: translateY(0);
    transition: transform 0.4s, box-shadow 0.4s;
}

.auth-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.5);
}

.card-header {
    text-align: center;
    margin-bottom: clamp(1.5rem, 4vw, 2.5rem);
}

.card-header h1 {
    font-size: clamp(2rem, 8vw, 3rem);
    font-weight: 800;
    margin-bottom: 0.5rem;
    background: linear-gradient(90deg, var(--secondary), var(--accent));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    letter-spacing: 1px;
    line-height: 1.2;
}

.card-header p {
    color: rgba(255, 255, 255, 0.7);
    font-size: clamp(0.9rem, 2.5vw, 1rem);
    line-height: 1.4;
}

/* Toggle de Tipo de Usuário - RESPONSIVO */
.user-type-toggle {
    display: flex;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 50px;
    padding: 4px;
    margin-bottom: clamp(1.5rem, 4vw, 2rem);
    gap: 4px;
}

.type-btn {
    flex: 1;
    padding: clamp(0.7rem, 2vw, 0.8rem);
    border: none;
    background: none;
    color: rgba(255, 255, 255, 0.7);
    font-weight: 600;
    font-size: clamp(0.8rem, 2vw, 0.9rem);
    cursor: pointer;
    border-radius: 50px;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
}

.type-btn i {
    font-size: clamp(0.9rem, 2vw, 1rem);
}

.type-btn.active {
    background: var(--gradient);
    color: #0f1819;
    box-shadow: 0 4px 15px rgba(122, 4, 235, 0.4);
}

/* Formulário - RESPONSIVO */
.auth-form {
    display: flex;
    flex-direction: column;
}

.form-group {
    margin-bottom: clamp(1.2rem, 3vw, 1.8rem);
}

.form-group label {
    display: block;
    margin-bottom: 0.6rem;
    font-weight: 500;
    color: var(--text-light);
    font-size: clamp(0.9rem, 2vw, 0.95rem);
}

.input-wrapper {
    position: relative;
    display: flex;
    align-items: center;
}

.input-wrapper .icon {
    position: absolute;
    left: clamp(12px, 3vw, 15px);
    color: rgba(255, 255, 255, 0.7);
    font-size: clamp(1rem, 2.5vw, 1.1rem);
}

.input-wrapper input {
    width: 100%;
    padding: clamp(12px, 3vw, 15px) clamp(12px, 3vw, 15px) clamp(12px, 3vw, 15px) clamp(40px, 8vw, 45px);
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-light);
    font-size: clamp(0.95rem, 2vw, 1rem);
    transition: all 0.3s ease;
}

.input-wrapper input:focus {
    outline: none;
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(255, 0, 226, 0.1);
    background: rgba(255, 255, 255, 0.1);
}

.input-wrapper input::placeholder {
    color: rgba(255, 255, 255, 0.4);
}

.input-wrapper input:invalid:not(:placeholder-shown) {
    border-color: #ff3860;
}

.input-wrapper input:valid:not(:placeholder-shown) {
    border-color: #09c372;
}

.show-password {
    position: absolute;
    right: clamp(12px, 3vw, 15px);
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.5);
    cursor: pointer;
    font-size: clamp(0.9rem, 2vw, 1rem);
    transition: color 0.3s;
    padding: 5px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: clamp(25px, 6vw, 30px);
    height: clamp(25px, 6vw, 30px);
}

.show-password:hover {
    color: var(--accent);
    background: rgba(255, 255, 255, 0.1);
}

/* Botão de Ação - RESPONSIVO */
.btn-auth {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: clamp(0.875rem, 3vw, 1rem);
    background: var(--gradient);
    color: #0f1819;
    font-weight: bold;
    font-size: clamp(0.95rem, 2vw, 1rem);
    text-decoration: none;
    border-radius: 10px;
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 4px 20px rgba(122, 4, 235, 0.4);
    margin-top: 0.5rem;
    overflow: hidden;
    position: relative;
    width: 100%;
}

.btn-auth span {
    position: relative;
    z-index: 2;
}

.btn-auth i {
    position: relative;
    z-index: 2;
    transition: transform 0.3s;
    font-size: clamp(0.9rem, 2vw, 1rem);
}

.btn-auth:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 30px rgba(122, 4, 235, 0.6);
}

.btn-auth:hover i {
    transform: translateX(5px);
}

.pulse-hover:hover {
    animation: pulse 1s infinite;
}

@keyframes pulse {
    0% { transform: translateY(-3px) scale(1); }
    50% { transform: translateY(-3px) scale(1.05); }
    100% { transform: translateY(-3px) scale(1); }
}

/* Links e Rodapé - RESPONSIVO */
.auth-footer {
    margin-top: clamp(1.5rem, 4vw, 2rem);
    text-align: center;
    font-size: clamp(0.85rem, 2vw, 0.9rem);
}

.auth-link {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    transition: color 0.3s;
    display: inline-block;
    margin: 0.4rem 0;
    font-size: inherit;
}

.auth-link:hover {
    color: var(--accent);
    text-decoration: underline;
}

/* Modal de Recuperação - RESPONSIVO */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(5px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
    padding: 1rem;
}

.modal-overlay.active {
    opacity: 1;
    visibility: visible;
}

.modal-card {
    background: var(--primary);
    padding: clamp(1.5rem, 4vw, 2.5rem);
    border-radius: 20px;
    width: 100%;
    max-width: min(450px, 95vw);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.1);
    position: relative;
    transform: translateY(20px);
    transition: transform 0.3s ease;
    max-height: 90vh;
    overflow-y: auto;
}

.modal-overlay.active .modal-card {
    transform: translateY(0);
}

.modal-header {
    margin-bottom: clamp(1.5rem, 4vw, 2rem);
    text-align: center;
}

.modal-header h2 {
    font-size: clamp(1.4rem, 5vw, 1.8rem);
    margin-bottom: 0.5rem;
    color: var(--text-light);
    line-height: 1.3;
}

.modal-header p {
    color: rgba(255, 255, 255, 0.7);
    font-size: clamp(0.85rem, 2.5vw, 0.95rem);
    line-height: 1.4;
}

.modal-close {
    position: absolute;
    top: clamp(15px, 4vw, 20px);
    right: clamp(15px, 4vw, 20px);
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.7);
    font-size: clamp(1.5rem, 4vw, 1.8rem);
    cursor: pointer;
    transition: color 0.3s;
    line-height: 1;
    padding: 5px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: clamp(30px, 8vw, 40px);
    height: clamp(30px, 8vw, 40px);
}

.modal-close:hover {
    color: var(--accent);
    background: rgba(255, 255, 255, 0.1);
}

/* Feedback de Recuperação - RESPONSIVO */
#recoveryFeedback {
    margin: 1rem 0;
    padding: clamp(0.8rem, 2vw, 1rem);
    border-radius: 8px;
    display: none;
    font-size: clamp(0.8rem, 2vw, 0.9rem);
    align-items: center;
    gap: 8px;
}

#recoveryFeedback.success {
    display: flex;
    background: rgba(9, 195, 114, 0.2);
    border: 1px solid #09c372;
    color: #09c372;
}

#recoveryFeedback.error {
    display: flex;
    background: rgba(255, 56, 96, 0.2);
    border: 1px solid #ff3860;
    color: #ff3860;
}

/* Sistema de Alertas Melhorado - RESPONSIVO */
.alert-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 16, 31, 0.95);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2000;
    opacity: 0;
    visibility: hidden;
    transition: all 0.4s ease;
    padding: 1rem;
}

.alert-overlay.visible {
    opacity: 1;
    visibility: visible;
}

.alert-modal {
    background: var(--primary);
    padding: clamp(1.5rem, 4vw, 2.5rem);
    border-radius: 20px;
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.5);
    border: 1px solid rgba(255, 255, 255, 0.15);
    max-width: min(450px, 90vw);
    width: 100%;
    text-align: center;
    transform: scale(0.9) translateY(-20px);
    transition: all 0.4s ease;
}

.alert-overlay.visible .alert-modal {
    transform: scale(1) translateY(0);
}

.alert-icon {
    font-size: clamp(2.5rem, 8vw, 3.5rem);
    margin-bottom: 1.5rem;
}

.alert-success .alert-icon {
    color: #09c372;
}

.alert-error .alert-icon {
    color: #ff3860;
}

.alert-warning .alert-icon {
    color: #ffdd57;
}

.alert-title {
    font-size: clamp(1.3rem, 4vw, 1.6rem);
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--text-light);
    line-height: 1.3;
}

.alert-message {
    font-size: clamp(0.9rem, 2.5vw, 1rem);
    line-height: 1.6;
    margin-bottom: 2rem;
    color: rgba(255, 255, 255, 0.9);
}

.alert-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}

.alert-btn {
    padding: clamp(0.7rem, 2vw, 0.8rem) clamp(1.25rem, 3vw, 1.5rem);
    border: none;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: clamp(0.9rem, 2vw, 0.95rem);
    min-width: 120px;
    flex: 1;
}

.alert-btn-primary {
    background: var(--gradient);
    color: var(--text-light);
}

.alert-btn-secondary {
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-light);
}

.alert-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
}

/* Mensagens de Erro Específicas - RESPONSIVO */
.login-error {
    background: linear-gradient(135deg, rgba(255, 56, 96, 0.15), rgba(255, 107, 157, 0.1));
    border: 1px solid rgba(255, 56, 96, 0.3);
    color: #ff6b9d;
    padding: clamp(0.8rem, 2vw, 1rem) clamp(1rem, 3vw, 1.5rem);
    border-radius: 10px;
    margin-bottom: 1.5rem;
    display: none;
    align-items: center;
    gap: 10px;
    font-weight: 500;
    backdrop-filter: blur(10px);
    font-size: clamp(0.85rem, 2vw, 0.95rem);
}

.login-error i {
    font-size: clamp(1rem, 2.5vw, 1.2rem);
    flex-shrink: 0;
}

.login-error.visible {
    display: flex;
    animation: slideInDown 0.4s ease;
}

@keyframes slideInDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Form de Redefinição de Senha - RESPONSIVO */
#resetForm {
    display: none;
}

#resetForm.visible {
    display: block;
    animation: fadeInUp 0.5s ease;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Campos de Nova Senha Estilizados - RESPONSIVO */
#resetForm .password-strength {
    margin-top: 0.8rem;
    display: none;
    opacity: 0;
    transform: translateY(-10px);
    transition: all 0.3s ease;
    align-items: center;
    gap: clamp(8px, 2vw, 12px);
    flex-wrap: wrap;
}

#resetForm .password-strength.visible {
    display: flex;
    opacity: 1;
    transform: translateY(0);
}

#resetForm .strength-bar-container {
    flex-grow: 1;
    height: 6px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 3px;
    overflow: hidden;
    min-width: 100px;
}

#resetForm .strength-bar {
    height: 100%;
    width: 0%;
    border-radius: 3px;
    transition: all 0.4s ease;
}

#resetForm .strength-bar.weak {
    background: linear-gradient(90deg, #ff3860, #ff6b9d);
    width: 33% !important;
}

#resetForm .strength-bar.medium {
    background: linear-gradient(90deg, #ffdd57, #ffb347);
    width: 66% !important;
}

#resetForm .strength-bar.strong {
    background: linear-gradient(90deg, #09c372, #00d4aa);
    width: 100% !important;
}

#resetForm .strength-text {
    font-size: clamp(0.8rem, 2vw, 0.85rem);
    font-weight: 600;
    min-width: 60px;
    text-align: right;
    flex-shrink: 0;
}

#resetForm .strength-text.weak { color: #ff3860; }
#resetForm .strength-text.medium { color: #ffdd57; }
#resetForm .strength-text.strong { color: #09c372; }

/* Feedback de Confirmação de Senha - RESPONSIVO */
.password-match-feedback {
    font-size: clamp(0.8rem, 2vw, 0.85rem);
    margin-top: 0.6rem;
    padding: 0.4rem 0;
    display: none;
    align-items: center;
    gap: 8px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.password-match-feedback.visible {
    display: flex;
}

.password-match-feedback.match {
    color: #09c372;
}

.password-match-feedback.no-match {
    color: #ff3860;
}

.password-match-feedback i {
    font-size: 1rem;
}

/* Estados de Loading Melhorados */
.btn-auth:disabled {
    opacity: 0.7;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
}

.btn-auth:disabled:hover {
    transform: none !important;
}

/* Feedback do Reset - RESPONSIVO */
#resetFeedback {
    margin: 1rem 0;
    padding: clamp(0.8rem, 2vw, 1rem) clamp(1rem, 3vw, 1.5rem);
    border-radius: 10px;
    display: none;
    align-items: center;
    gap: 10px;
    font-weight: 500;
    backdrop-filter: blur(10px);
    font-size: clamp(0.85rem, 2vw, 0.95rem);
}

#resetFeedback.success {
    display: flex;
    background: rgba(9, 195, 114, 0.15);
    border: 1px solid rgba(9, 195, 114, 0.3);
    color: #09c372;
}

#resetFeedback.error {
    display: flex;
    background: rgba(255, 56, 96, 0.15);
    border: 1px solid rgba(255, 56, 96, 0.3);
    color: #ff6b9d;
}

/* =======================
   Melhorias de Acessibilidade
   ======================= */
@media (prefers-reduced-motion: reduce) {
    .auth-card,
    .btn-auth,
    .alert-btn,
    .show-password,
    .type-btn {
        transition: none;
    }

    .auth-card:hover,
    .btn-auth:hover,
    .alert-btn:hover {
        transform: none;
    }

    .pulse-hover:hover {
        animation: none;
    }

    .login-error.visible,
    #resetForm.visible {
        animation: none;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
    .auth-card,
    .modal-card,
    .alert-modal {
        border: 2px solid var(--text-light);
    }

    .input-wrapper input {
        border: 2px solid var(--text-light);
    }

    .type-btn {
        border: 1px solid var(--text-light);
    }
}

/* =======================
   Responsividade Avançada
   ======================= */
@media (max-width: 360px) {
    .auth-card {
        padding: 1.25rem;
        border-radius: 15px;
    }

    .card-header h1 {
        font-size: 1.8rem;
    }

    .type-btn {
        font-size: 0.75rem;
        padding: 0.6rem;
    }

    .input-wrapper input {
        padding: 10px 10px 10px 35px;
    }

    .input-wrapper .icon {
        left: 10px;
        font-size: 0.9rem;
    }

    .show-password {
        right: 10px;
        font-size: 0.9rem;
    }
}

/* Garantir que modais não vazem em telas muito pequenas */
@media (max-height: 600px) {
    .modal-card {
        max-height: 85vh;
        overflow-y: auto;
    }

    .auth-card {
        margin: 1rem 0;
    }
}

