import express from "express";
import multer from "multer";
import path from "path";
import fs from "fs";
import { fileURLToPath } from "url";
import { atualizarFotoPerfil, obterFotoPerfil, removerFotoPerfil,alterarSenha } from "../controllers/perfilController.js";
import { autenticarJWT as autenticarToken } from "../middlewares/authMiddleware.js";

const router = express.Router();
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// ===============================
// 📁 Configuração do Multer (Upload de fotos)
// ===============================
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    // Caminho absoluto até a pasta uploads/perfis
    const uploadDir = path.join(__dirname, "..", "uploads", "perfis");

    try {
      fs.mkdirSync(uploadDir, { recursive: true });
      cb(null, uploadDir);
    } catch (err) {
      console.error("Erro ao criar pasta de upload:", err);
      cb(err);
    }
  },
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    // Nome: <userId>-<timestamp>.ext
    cb(null, `${req.user.id}-${Date.now()}${ext}`);
  },
});

const upload = multer({
  storage,
  limits: { fileSize: 2 * 1024 * 1024 }, // máximo 2MB
  fileFilter: (req, file, cb) => {
    const allowed = /jpeg|jpg|png/;
    const isValid = allowed.test(path.extname(file.originalname).toLowerCase());
    cb(isValid ? null : new Error("Formato inválido. Use JPG ou PNG."), isValid);
  },
});

// ===============================
// 🖼️ Upload de foto (autenticado)
// ===============================
router.post("/upload-foto", autenticarToken, upload.single("foto"), atualizarFotoPerfil);

// ===============================
// 🔐 Obter foto de perfil (autenticado)
// ===============================
router.get("/foto", autenticarToken, (req, res) => {
  const userId = req.user.id;
  const uploadDir = path.join(__dirname, "..", "uploads", "perfis");

  try {
    // Procura o arquivo que começa com o ID do usuário
    const arquivos = fs.readdirSync(uploadDir);
    const foto = arquivos.find((arq) => arq.startsWith(`${userId}-`));

    if (!foto) {
      // Caso não tenha foto, retorna uma padrão
      const defaultPath = path.join(__dirname, "..", "uploads", "default-avatar.png");
      if (fs.existsSync(defaultPath)) {
        return res.sendFile(defaultPath);
      }
      return res.status(404).json({ message: "Foto não encontrada" });
    }

    const fotoPath = path.join(uploadDir, foto);
    res.sendFile(fotoPath);
  } catch (err) {
    console.error("Erro ao obter foto:", err);
    res.status(500).json({ message: "Erro ao carregar a foto" });
  }
});

// ===============================
// 🗑️ Remover foto (autenticado)
// ===============================
router.delete("/remover-foto", autenticarToken, removerFotoPerfil);



// ===============================
// 🔐 Alterar senha (autenticado)
// ===============================
router.put("/alterar-senha", autenticarToken, alterarSenha);



// ===============================
// ✅ Exporta as rotas
// ===============================
export default router;

main/front-end/assets/css/minhas-ordens..content:
/* =======================
   MINHAS ORDENS - SUPORTE
   minhas-ordens.css (Versão Final)
   ======================= */

/* =======================
   Variáveis Globais
   ======================= */
:root {
    --primary-bg: #ffffff;
    --secondary-bg: #f5f7fa;
    --text-dark: #101728;
    --text-medium: #666;
    --text-light: #999;
    --border-light: #e1e5eb;
    --card-shadow: 0 4px 15px rgba(0, 0, 0, 0.05);
    --accent: #7a04eb;
    --secondary: #555;
    --success: #4CAF50;
    --warning: #FF9800;
    --info: #2196F3;
    --danger: #F44336;
}

/* =======================
   Layout Principal
   ======================= */
.suporte-content {
    padding: 2rem;
    background: var(--secondary-bg);
    min-height: calc(100vh - 70px);
}

.orders-header {
    margin-bottom: 2rem;
}

.orders-header h1 {
    font-size: 2rem;
    color: var(--text-dark);
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 1.5rem;
}

.orders-header h1 i {
    color: var(--accent);
}

/* =======================
   Filtros Modernos
   ======================= */
.filters-container {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem;
    box-shadow: var(--card-shadow);
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.filter-group {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    align-items: center;
}

/* Botões de Filtro (Tabs) */
.filter-btn {
    padding: 0.6rem 1.2rem;
    border-radius: 50px;
    border: 1px solid var(--border-light);
    background: #f9f9f9;
    color: var(--text-medium);
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.9rem;
    font-weight: 500;
}

.filter-btn:hover {
    background: #e1e5eb;
    transform: translateY(-2px);
}

.filter-btn.active {
    background: var(--accent);
    color: #fff;
    border-color: var(--accent);
    box-shadow: 0 4px 12px rgba(122, 4, 235, 0.2);
}

/* Inputs de Busca e Data */
.search-box {
    position: relative;
    flex: 1;
    min-width: 250px;
}

.search-box i {
    position: absolute;
    left: 1rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-light);
}

.search-box input {
    width: 100%;
    padding: 0.8rem 1rem 0.8rem 2.8rem;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    font-size: 0.95rem;
    transition: border-color 0.3s;
    background: #fff;
}

.search-box input:focus {
    outline: none;
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

.date-filter {
    display: flex;
    align-items: center;
    gap: 0.8rem;
    background: #f9f9f9;
    padding: 0.5rem;
    border-radius: 8px;
    border: 1px solid var(--border-light);
}

.date-filter input {
    border: none;
    background: transparent;
    font-family: inherit;
    color: var(--text-medium);
    padding: 0.2rem;
}

.date-filter label {
    font-size: 0.9rem;
    color: var(--text-dark);
    font-weight: 600;
}

.small-btn {
    padding: 0.5rem 0.8rem;
    border-radius: 6px;
    background: var(--accent);
    color: #fff;
    border: none;
    cursor: pointer;
    transition: background 0.3s;
}

.small-btn:hover { background: #6003b0; }

/* =======================
   Cards de Estatísticas
   ======================= */
.stats-summary {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 1.5rem;
    margin: 2rem 0;
}

.stat-card {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem;
    text-align: center;
    box-shadow: var(--card-shadow);
    border-top: 4px solid var(--secondary);
    transition: transform 0.3s;
}

.stat-card:hover { transform: translateY(-5px); }

.stat-card.pending { border-color: var(--warning); }
.stat-card.in-progress { border-color: var(--info); }
.stat-card.completed { border-color: var(--success); }

.stat-value {
    font-size: 2rem;
    font-weight: 700;
    color: var(--text-dark);
    margin-bottom: 0.2rem;
}

.stat-label {
    font-size: 0.85rem;
    color: var(--text-medium);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 600;
}

/* =======================
   Lista de Ordens (Grid)
   ======================= */
.orders-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.order-card {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem;
    box-shadow: var(--card-shadow);
    border: 1px solid var(--border-light);
    transition: all 0.3s;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

.order-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 25px rgba(0,0,0,0.1);
    border-color: var(--accent);
}

/* Borda lateral de status */
.order-card::before {
    content: '';
    position: absolute;
    left: 0; top: 0; bottom: 0; width: 5px;
}

.order-card.pendente::before { background: var(--warning); }
.order-card.em-andamento::before { background: var(--info); }
.order-card.concluida::before { background: var(--success); }
.order-card.nao-concluida::before { background: var(--danger); }

/* Cabeçalho do Card */
.order-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding-bottom: 0.8rem;
    border-bottom: 1px solid #f0f0f0;
}

.order-id {
    font-weight: 700;
    color: var(--text-dark);
    background: #f0f2f5;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.85rem;
}

.order-date {
    font-size: 0.8rem;
    color: var(--text-medium);
}

/* Status Badge */
.order-status {
    padding: 0.3rem 0.8rem;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    gap: 5px;
}

.pendente .order-status { background: rgba(255,152,0,0.1); color: var(--warning); }
.em-andamento .order-status { background: rgba(33,150,243,0.1); color: var(--info); }
.concluida .order-status { background: rgba(76,175,80,0.1); color: var(--success); }
.nao-concluida .order-status { background: rgba(244, 67, 54, 0.1); color: var(--danger); }

/* Conteúdo do Card */
.order-content h3 {
    font-size: 1.1rem;
    color: var(--text-dark);
    margin-bottom: 0.6rem;
    line-height: 1.4;
    font-weight: 600;
}

.order-description {
    color: var(--text-medium);
    font-size: 0.9rem;
    margin-bottom: 1rem;
    display: -webkit-box;
    -webkit-line-clamp: 2; /* Limita a 2 linhas */
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.order-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.8rem;
    font-size: 0.8rem;
    color: var(--text-medium);
    margin-top: auto;
}

.order-meta span {
    display: flex;
    align-items: center;
    gap: 6px;
    background: #f8f9fa;
    padding: 4px 8px;
    border-radius: 6px;
}

/* Ações (Botões no Card) */
.order-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.8rem;
    justify-content: flex-end;
}

.btn-small {
    padding: 0.6rem 1rem;
    font-size: 0.85rem;
    border-radius: 6px;
    border: none;
    cursor: pointer;
    font-weight: 500;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    transition: all 0.2s;
}

.btn-view { background: rgba(122,4,235,0.1); color: var(--accent); }
.btn-view:hover { background: var(--accent); color: white; }

.btn-feedback { background: rgba(255,193,7,0.1); color: #FFC107; }
.btn-feedback:hover { background: #FFC107; color: white; }

.btn-reopen { background: rgba(244,67,54,0.1); color: var(--danger); }
.btn-reopen:hover { background: var(--danger); color: white; }

/* =======================
   Estado Vazio (No Orders)
   ======================= */
.no-orders {
    text-align: center;
    padding: 3rem;
    grid-column: 1 / -1; /* Ocupa toda a largura */
    color: var(--text-medium);
}

.no-orders i {
    font-size: 3rem;
    color: var(--border-light);
    margin-bottom: 1rem;
}

/* =======================
   RESPONSIVIDADE
   ======================= */
@media (max-width: 768px) {
    .suporte-content {
        padding: 1rem;
    }

    .filters-container {
        padding: 1rem;
    }

    .filter-group {
        flex-direction: column;
        align-items: stretch;
        gap: 1rem;
    }

    .date-filter {
        flex-wrap: wrap;
    }

    .orders-list {
        grid-template-columns: 1fr; /* 1 coluna no mobile */
    }

    .stat-card {
        padding: 1rem;
    }

    .stat-value {
        font-size: 1.5rem;
    }
}

