    }

    .toast-container {
        right: 10px;
        left: 10px;
        max-width: none;
    }

    .toast {
        max-width: none;
    }

    .confirm-modal .modal-content {
        margin: 1rem;
        padding: 1.5rem;
    }

    .confirm-actions {
        flex-direction: column;
    }

    .confirm-btn {
        width: 100%;
        min-width: auto;
    }

    .alert-modal {
        padding: 1.5rem;
    }

    .alert-actions {
        flex-direction: column;
    }

    .alert-btn {
        width: 100%;
    }

    /* Indicador de scroll para mobile */
    .table-responsive {
        position: relative;
        border: 1px solid var(--border-light);
        border-radius: 8px;
    }

    .table-responsive::after {
        position: absolute;
        top: 50%;
        right: 10px;
        transform: translateY(-50%);
        background: var(--secondary);
        color: white;
        padding: 0.25rem 0.5rem;
        border-radius: 12px;
        font-size: 0.7rem;
        opacity: 0.8;
        animation: pulse 2s infinite;
        pointer-events: none;
        z-index: 2;
    }
}

/* Mobile */
@media (max-width: 576px) {
    .page-header h1 {
        font-size: 1.4rem;
    }

    .page-header p {
        font-size: 0.9rem;
    }

    .filters-section {
        padding: 1rem;
        border-radius: 8px;
    }

    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 0.5rem;
    }

    .stat-card {
        padding: 0.75rem;
        text-align: center;
        flex-direction: column;
        gap: 0.5rem;
    }

    .stat-icon {
        width: 35px;
        height: 35px;
        font-size: 1rem;
    }

    .stat-info h3 {
        font-size: 1.2rem;
    }

    .stat-info p {
        font-size: 0.8rem;
    }

    .table-header h3 {
        font-size: 1.1rem;
    }

    .btn {
        padding: 0.7rem 1rem;
        font-size: 0.9rem;
    }

    .patrimonio-table {
        min-width: 650px;
    }

    .patrimonio-table th,
    .patrimonio-table td {
        padding: 0.6rem 0.4rem;
    }

    .pagination {
        padding: 1rem;
        gap: 0.3rem;
    }

    .pagination-btn {
        width: 35px;
        height: 35px;
        font-size: 0.85rem;
    }

    .modal-content {
        width: 98%;
        margin: 0.5rem;
    }

    .modal-header,
    .modal-body,
    .modal-footer {
        padding: 1rem;
    }

    .modal-footer {
        flex-direction: column;
        gap: 0.5rem;
    }

    .modal-footer .btn {
        width: 100%;
    }
}

/* Mobile Muito Pequeno */
@media (max-width: 480px) {
    .filter-group:last-child {
        flex-direction: row;
        justify-content: space-between;
    }

    .btn {
        flex: 1;
        justify-content: center;
    }

    .table-actions {
        flex-direction: column;
        gap: 0.5rem;
    }

    .table-actions .btn {
        width: 100%;
    }

    .patrimonio-table {
        min-width: 600px;
    }

    .patrimonio-table td:nth-child(3) {
        max-width: 120px;
    }

    .actions-cell {
        flex-direction: column;
        gap: 0.2rem;
    }

    .btn-table {
        width: 100%;
        height: 32px;
    }

    .modal-content {
        border-radius: 8px;
    }

    .form-modal {
        padding: 1.25rem;
    }

    .toast {
        padding: 1rem;
    }

    .toast-content {
        min-width: 0;
    }

    .confirm-modal .modal-content {
        padding: 1.25rem;
    }

    .alert-modal {
        padding: 1.25rem;
    }

    .alert-title {
        font-size: 1.3rem;
    }

    .alert-message {
        font-size: 0.9rem;
    }
}

/* Mobile Extra Pequeno */
@media (max-width: 360px) {
    .admin-content {
        padding: 0.75rem;
    }

    .stat-card {
        padding: 0.75rem;
    }

    .stat-icon {
        width: 35px;
        height: 35px;
        font-size: 1rem;
    }

    .stat-info h3 {
        font-size: 1.2rem;
    }

    .patrimonio-table {
        min-width: 550px;
        font-size: 0.8rem;
    }

    .pagination-btn {
        width: 32px;
        height: 32px;
        font-size: 0.8rem;
    }
}

/* =======================
   Acessibilidade
   ======================= */
@media (prefers-reduced-motion: reduce) {
    .table-responsive {
        scroll-behavior: auto;
    }

    .btn-table,
    .stat-card,
    .modal-content {
        transition: none;
        animation: none;
    }

    .btn-table:hover,
    .stat-card:hover {
        transform: none;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
    .patrimonio-table {
        border: 2px solid #000;
    }

    .patrimonio-table th {
        background: #000;
        color: #fff;
    }

    .table-responsive::-webkit-scrollbar-thumb {
        background: #000;
    }
}

