main/front-end/assets/css/cadastro.css.content:
/* =======================
   Cadastro - RESPONSIVO
   ======================= */
/* Container principal */
.cadastro-container {
    max-width: 1200px;
    margin: 2rem auto;
    padding: clamp(1.5rem, 4vw, 2rem);
    background: rgba(16, 23, 40, 0.95);
    backdrop-filter: blur(15px);
    border-radius: 15px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

/* Header */
.cadastro-header {
    margin-bottom: 2rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center;
}

.cadastro-header h1 {
    font-size: clamp(1.5rem, 4vw, 2rem);
    color: var(--text-light);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-bottom: 0.5rem;
    flex-wrap: wrap;
}

.cadastro-header h1 i {
    color: var(--accent);
    font-size: clamp(1.4rem, 3vw, 1.8rem);
}

.cadastro-header p {
    color: rgba(255, 255, 255, 0.7);
    font-size: clamp(0.9rem, 2vw, 1rem);
    line-height: 1.4;
}

/* Grid - RESPONSIVO */
.cadastro-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2rem;
}

@media (min-width: 768px) {
    .cadastro-grid {
        grid-template-columns: 1fr 1fr;
        gap: 2.5rem;
    }
}

.cadastro-column {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

/* Form Groups - MELHORADO */
.form-group {
    margin-bottom: 0;
    position: relative;
}

.form-group label {
    display: block;
    margin-bottom: 0.6rem;
    color: var(--text-light);
    font-weight: 600;
    font-size: clamp(0.9rem, 2vw, 0.95rem);
    display: flex;
    align-items: center;
    gap: 10px;
}

.form-group label i {
    width: 20px;
    color: var(--accent);
    font-size: 1.1rem;
    flex-shrink: 0;
}

.form-group input {
    width: 100%;
    padding: clamp(12px, 3vw, 14px) clamp(14px, 3vw, 16px);
    border-radius: 10px;
    border: 2px solid rgba(255, 255, 255, 0.15);
    background: rgba(255, 255, 255, 0.08);
    color: var(--text-light);
    font-size: clamp(0.95rem, 2vw, 1rem);
    transition: all 0.3s ease;
}

.form-group input:focus {
    outline: none;
    border-color: var(--accent);
    background: rgba(255, 255, 255, 0.12);
    box-shadow: 0 0 0 4px rgba(255, 0, 226, 0.15);
}

.form-group input.invalid {
    border-color: #ff3860;
    box-shadow: 0 0 0 4px rgba(255, 56, 96, 0.15);
}

.form-group input:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Password Wrapper - RESPONSIVO */
.password-wrapper {
    position: relative;
}

.password-wrapper input {
    padding-right: clamp(45px, 10vw, 50px);
}

.show-password {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.5);
    cursor: pointer;
    font-size: clamp(1rem, 2vw, 1.1rem);
    padding: 5px;
    border-radius: 4px;
    transition: all 0.3s;
    width: clamp(30px, 8vw, 35px);
    height: clamp(30px, 8vw, 35px);
    display: flex;
    align-items: center;
    justify-content: center;
}

.show-password:hover {
    color: var(--accent);
    background: rgba(255, 255, 255, 0.1);
}

/* Password Strength - RESPONSIVO */
.password-strength {
    margin-top: 0.8rem;
    display: none;
    opacity: 0;
    transform: translateY(-10px);
    transition: all 0.3s ease;
}

.password-strength.visible {
    display: flex;
    opacity: 1;
    transform: translateY(0);
    align-items: center;
    gap: clamp(8px, 2vw, 12px);
    flex-wrap: wrap;
}

.strength-bar-container {
    flex-grow: 1;
    height: 6px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 3px;
    overflow: hidden;
    min-width: 100px;
}

.strength-bar {
    height: 100%;
    width: 0%;
    border-radius: 3px;
    transition: all 0.4s ease;
}

.strength-bar.weak {
    background: linear-gradient(90deg, #ff3860, #ff6b9d);
    width: 33% !important;
}

.strength-bar.medium {
    background: linear-gradient(90deg, #ffdd57, #ffb347);
    width: 66% !important;
}

.strength-bar.strong {
    background: linear-gradient(90deg, #09c372, #00d4aa);
    width: 100% !important;
}

.strength-text {
    font-size: clamp(0.8rem, 2vw, 0.85rem);
    font-weight: 600;
    min-width: 60px;
    text-align: right;
    flex-shrink: 0;
}

.strength-text.weak { color: #ff3860; }
.strength-text.medium { color: #ffdd57; }
.strength-text.strong { color: #09c372; }

/* Password Match Feedback - RESPONSIVO */
.password-match-feedback {
    font-size: clamp(0.8rem, 2vw, 0.85rem);
    margin-top: 0.6rem;
    padding: 0.4rem 0;
    display: none;
    align-items: center;
    gap: 8px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.password-match-feedback.visible {
    display: flex;
}

.password-match-feedback.match {
    color: #09c372;
}

.password-match-feedback.no-match {
    color: #ff3860;
}

.password-match-feedback i {
    font-size: 1rem;
    flex-shrink: 0;
}

/* Form Actions - RESPONSIVO */
.form-actions {
    display: flex;
    justify-content: flex-end;
    gap: clamp(1rem, 3vw, 1.2rem);
    margin-top: 2.5rem;
    padding-top: 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    flex-wrap: wrap;
}

@media (max-width: 480px) {
    .form-actions {
        flex-direction: column;
        gap: 1rem;
    }
}

.btn-submit {
    padding: clamp(0.875rem, 3vw, 1rem) clamp(1.5rem, 4vw, 2rem);
    background: var(--gradient);
    color: var(--text-light);
    font-weight: 700;
    border: none;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: clamp(0.95rem, 2vw, 1rem);
    position: relative;
    overflow: hidden;
    flex-shrink: 0;
}

.btn-submit:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 25px rgba(122, 4, 235, 0.5);
}

.btn-submit:disabled {
    opacity: 0.7;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

.btn-submit:disabled:hover {
    transform: none;
}

.btn-cancel {
    padding: clamp(0.875rem, 3vw, 1rem) clamp(1.5rem, 4vw, 1.8rem);
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-light);
    font-weight: 600;
    border: none;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: clamp(0.95rem, 2vw, 1rem);
    flex-shrink: 0;
}

.btn-cancel:hover {
    background: rgba(255, 255, 255, 0.2);
    transform: translateY(-2px);
}

@media (max-width: 480px) {
    .btn-submit,
    .btn-cancel {
        width: 100%;
        justify-content: center;
    }
}

/* =======================
   Popups de Alerta - RESPONSIVOS
   ======================= */
.alert-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 16, 31, 0.95);
    backdrop-filter: blur(5px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
    padding: 1rem;
}

.alert-overlay.visible {
    opacity: 1;
    visibility: visible;
}

.alert-modal {
    background: var(--primary);
    padding: clamp(1.5rem, 4vw, 2.5rem);
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    border: 1px solid rgba(255, 255, 255, 0.1);
    max-width: min(450px, 90vw);
    width: 100%;
    text-align: center;
    transform: scale(0.9);
    transition: all 0.3s ease;
}

.alert-overlay.visible .alert-modal {
    transform: scale(1);
}

.alert-icon {
    font-size: clamp(2.5rem, 8vw, 3rem);
    margin-bottom: 1.5rem;
}

.alert-success .alert-icon {
    color: #09c372;
}

.alert-error .alert-icon {
    color: #ff3860;
}

.alert-warning .alert-icon {
    color: #ffdd57;
}

.alert-title {
    font-size: clamp(1.25rem, 4vw, 1.5rem);
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--text-light);
    line-height: 1.3;
}

.alert-message {
    font-size: clamp(0.9rem, 2vw, 1rem);
    line-height: 1.6;
    margin-bottom: 2rem;
    color: rgba(255, 255, 255, 0.9);
}

.alert-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}

@media (max-width: 480px) {
    .alert-actions {
        flex-direction: column;
    }
}

.alert-btn {
    padding: clamp(0.7rem, 2vw, 0.8rem) clamp(1.25rem, 3vw, 1.5rem);
    border: none;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: clamp(0.9rem, 2vw, 0.95rem);
    flex: 1;
    min-width: 120px;
}

.alert-btn-primary {
    background: var(--gradient);
    color: var(--text-light);
}

.alert-btn-secondary {
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-light);
}

.alert-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
}

/* Success Overlay - RESPONSIVO */
.success-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 16, 31, 0.95);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2000;
    opacity: 0;
    visibility: hidden;
    transition: all 0.5s ease;
    padding: 1rem;
}

.success-overlay.visible {
    opacity: 1;
    visibility: visible;
}

.success-content {
    text-align: center;
    color: var(--text-light);
    transform: translateY(20px);
    transition: all 0.5s ease;
    max-width: min(500px, 90vw);
    width: 100%;
}

.success-overlay.visible .success-content {
    transform: translateY(0);
}

.success-icon {
    font-size: clamp(3rem, 10vw, 4rem);
    color: #09c372;
    margin-bottom: 1.5rem;
    animation: bounce 1s ease;
}

@keyframes bounce {
    0%, 20%, 50%, 80%, 100% {transform: translateY(0);}
    40% {transform: translateY(-20px);}
    60% {transform: translateY(-10px);}
}

.success-title {
    font-size: clamp(1.5rem, 5vw, 2rem);
    font-weight: 700;
    margin-bottom: 1rem;
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    line-height: 1.3;
}

.success-message {
    font-size: clamp(1rem, 2.5vw, 1.1rem);
    color: rgba(255, 255, 255, 0.9);
    margin-bottom: 2rem;
    line-height: 1.5;
}

/* =======================
   Melhorias de Acessibilidade
   ======================= */
@media (prefers-reduced-motion: reduce) {
    .btn-submit,
    .btn-cancel,
    .alert-btn,
    .show-password {
        transition: none;
    }

    .btn-submit:hover,
    .btn-cancel:hover,
    .alert-btn:hover {
        transform: none;
    }

    .success-icon {
        animation: none;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
    .cadastro-container {
        border: 2px solid var(--text-light);
    }

    .form-group input {
        border: 2px solid var(--text-light);
    }

    .btn-cancel {
        border: 1px solid var(--text-light);
    }
}

/* =======================
   Estados de Loading Melhorados
   ======================= */
.btn-submit.loading {
    position: relative;
    color: transparent;
}

.btn-submit.loading::after {
    content: '';
    position: absolute;
    width: 20px;
    height: 20px;
    top: 50%;
    left: 50%;
    margin-left: -10px;
    margin-top: -10px;
    border: 2px solid transparent;
    border-top: 2px solid var(--text-light);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

