// Efeito de digitação no subtítulo
document.addEventListener('DOMContentLoaded', () => {
    const subtitle = document.querySelector('.subtitle');
    if (!subtitle) return;
    
    const text = subtitle.textContent;
    subtitle.textContent = '';
    subtitle.style.borderRight = '2px solid var(--accent)';
    subtitle.style.display = 'inline-block';
    subtitle.style.minHeight = '1.5em';
    
    let i = 0;
    const typingEffect = setInterval(() => {
        if (i < text.length) {
            subtitle.textContent += text.charAt(i);
            i++;
        } else {
            clearInterval(typingEffect);
            // Mantém o cursor piscando por mais 2 segundos depois de terminar
            setTimeout(() => {
                subtitle.style.borderRight = 'none';
            }, 2000);
        }
    }, 50);
});

// Garante que não há scroll
window.addEventListener('load', () => {
    document.body.style.overflow = 'hidden';
});

main/front-end/assets/css/ordens-totais..content:
:root {
  --bg: #f4f7ff;
  --sidebar-bg: #1e2538;
  --sidebar-hover: #2a3560;
  --sidebar-accent: #4ade80;
  --text-dark: #1f2937;
  --text-light: #6b7280;
  --primary: #2563eb;
  --success: #22c55e;
  --warning: #fbbf24;
  --danger: #ef4444;
  --card-bg: #ffffff;
  --shadow: 0 8px 20px rgba(0,0,0,0.08);
  --transition: 0.35s ease;
}

/* RESET */
* {margin:0; padding:0; box-sizing:border-box; font-family:'Poppins', sans-serif;}
body {background:var(--bg); color:var(--text-dark); line-height:1.6; display:flex; flex-direction:column; min-height:100vh;}

/* HEADER */
.header {background: linear-gradient(90deg,#20293a,#2b3448); color:#fff; padding:1rem 2rem; display:flex; justify-content:space-between; align-items:center; box-shadow:var(--shadow); position:sticky; top:0; z-index:999; border-bottom:1px solid rgba(255,255,255,0.1);}
.header h1 {font-size:1.75rem; display:flex; align-items:center; gap:0.6rem;}
.user-info button {background:var(--danger); color:#fff; border:none; padding:0.55rem 1.2rem; border-radius:12px; cursor:pointer; font-weight:600; transition:var(--transition);}
.user-info button:hover {transform:scale(1.05); background:#dc2626;}

/* LAYOUT */
.main-container {display:flex; flex:1; min-height:100vh;}
.sidebar {background:var(--sidebar-bg); min-width:220px; padding-top:1.5rem; color:white; box-shadow:4px 0 12px rgba(0,0,0,0.1);}
.sidebar ul {list-style:none; padding:0;}
.sidebar li {margin-bottom:0.5rem;}
.sidebar a {display:flex; align-items:center; color:#d1d5db; padding:1rem 1.5rem; text-decoration:none; border-radius:8px; font-weight:500; transition:var(--transition);}
.sidebar a i {margin-right:10px; width:20px; text-align:center;}
.sidebar a:hover, .sidebar a.active {background:var(--sidebar-hover); color:#fff; border-left:4px solid var(--sidebar-accent); transform:translateX(4px);}

/* CONTEÚDO */
.content {flex:1; padding:2rem 2.5rem; display:flex; flex-direction:column; gap:1.5rem;}
.content h2 {font-size:2rem; display:flex; align-items:center; gap:0.5rem; font-weight:700;}

/* FILTROS */
.filters {display:flex; gap:1rem; flex-wrap:wrap; margin-bottom:1rem;}
.filters input, .filters select {padding:0.6rem 1rem; border-radius:10px; border:1px solid #ccc; outline:none; transition:0.3s;}
.filters input:focus, .filters select:focus {border-color:var(--primary); box-shadow:0 0 8px rgba(37,99,235,0.2);}

/* TABELA */
.table-container {overflow-x:auto;}
.orders-table {width:100%; border-collapse:collapse; background:var(--card-bg); border-radius:12px; overflow:hidden; box-shadow:var(--shadow);}
.orders-table th, .orders-table td {padding:0.85rem 1rem; text-align:left;}
.orders-table th {background:#f1f5f9; color:var(--text-dark); font-weight:600; font-size:0.95rem;}
.orders-table tr {border-bottom:1px solid #e5e7eb;}
.orders-table tr:last-child {border-bottom:none; transition:background 0.3s;}
.orders-table tr:hover {background:#f3f4f6;}

/* STATUS */
.status {padding:0.25rem 0.7rem; border-radius:8px; font-weight:600; font-size:0.85rem; color:white; text-transform:uppercase;}
.status.pending {background:var(--warning);}
.status.in-progress {background:var(--primary);}
.status.concluida {background:var(--success);}

/* AÇÕES */
.orders-table button {border:none; background:none; cursor:pointer; font-size:0.9rem; margin-right:0.3rem; transition:var(--transition);}
.orders-table button.view {color:var(--primary);}
.orders-table button.edit {color:#2563eb;}
.orders-table button.delete {color:var(--danger);}
.orders-table button:hover {transform:scale(1.1);}

/* RESPONSIVIDADE */
@media(max-width:992px){.main-container{flex-direction:column;}.sidebar{width:100%;display:flex;overflow-x:auto;}.sidebar ul{display:flex; flex-direction:row; gap:0.5rem; padding:0.5rem;}.sidebar a{border-left:none; border-bottom:3px solid transparent; font-size:0.9rem;}.sidebar a:hover,.sidebar a.active{border-left:none; border-bottom:3px solid var(--sidebar-accent);}}
@media(max-width:600px){.header{flex-direction:column; align-items:flex-start; gap:0.5rem;}.filters{flex-direction:column;}.orders-table th, .orders-table td{padding:0.6rem; font-size:0.85rem;}}

/* Garantir que os botões fiquem lado a lado */
.orders-table td:last-child {
  display: flex;
  gap: 0.5rem;  /* espaço entre os botões */
  flex-wrap: nowrap; /* evita quebra de linha */
}
/* =======================
   Botões de ação
======================= */
.orders-table button {
  border: none;
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  transition: var(--transition);
}

.orders-table button i {
  font-size: 1rem;
}

/* Cores por ação */
.orders-table button.view {
  background: var(--primary);
  color: #fff;
}
.orders-table button.edit {
  background: #8b5cf6; /* roxo premium */
  color: #fff;
}
.orders-table button.delete {
  background: var(--danger);
  color: #fff;
}

/* Hover animado */
.orders-table button:hover {
  transform: scale(1.1);
  filter: brightness(1.15);
}

