/* =======================
   perfil.css
   (Compartilhado: Admin, Professor, Suporte)
   ======================= */

/* Variáveis para garantir consistência caso falte no global */
:root {
    --primary-dark: #101728;
    --secondary: #7a04eb;
    --accent: #ff00e2;
    --text-dark: #333;
    --text-medium: #666;
    --border-light: #e1e5eb;
    --success: #4CAF50;
    --danger: #F44336;
    --warning: #FF9800;
    --info: #2196F3;
}

.profile-header {
    margin-bottom: 2rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--border-light);
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
}

.profile-header h1 {
    font-size: 1.8rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 0.8rem;
    margin: 0;
}

.profile-card {
    background: #fff;
    border-radius: 12px;
    padding: 2.5rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    max-width: 900px;
    margin: 0 auto; /* Centraliza em telas grandes */
}

.profile-section {
    margin-bottom: 3rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid var(--border-light);
}

.profile-section:last-child {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.profile-section h2 {
    font-size: 1.4rem;
    color: var(--primary-dark);
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 0.8rem;
}

/* Foto de Perfil */
.photo-upload {
    display: flex;
    flex-wrap: wrap;
    gap: 2.5rem;
    align-items: center;
}

.photo-preview {
    position: relative;
    width: 140px;
    height: 140px;
    flex-shrink: 0;
}

.profile-photo {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
    border: 4px solid var(--secondary);
    transition: all 0.3s;
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.2);
}

.photo-preview:hover .profile-photo {
    border-color: var(--accent);
    transform: scale(1.02);
}

.change-photo-btn {
    position: absolute;
    bottom: 5px;
    right: 5px;
    width: 40px;
    height: 40px;
    background: var(--secondary);
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    border: 3px solid white;
    transition: all 0.3s;
    box-shadow: 0 2px 5px rgba(0,0,0,0.2);
}

.change-photo-btn:hover {
    background: var(--accent);
    transform: scale(1.1);
}

.upload-controls {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    flex: 1;
    min-width: 250px;
}

.upload-hint {
    color: var(--text-medium);
    font-size: 0.85rem;
    margin-top: 0.5rem;
}

/* =======================
   Formulários (Perfil.css Ajustado)
   ======================= */

.form-group {
    margin-bottom: 1.5rem;
    position: relative;
}

.form-group label {
    display: block;
    margin-bottom: 0.6rem;
    font-weight: 600;
    color: var(--primary-dark);
    font-size: 0.95rem;
}

/* Container relativo para posicionar ícones */
.input-with-icon {
    position: relative;
    width: 100%;
}

/* Ícone da Esquerda (Cadeado/User) */
.input-with-icon i.fas:not(.fa-eye):not(.fa-eye-slash) {
    position: absolute;
    left: 15px; /* Mais afastado da borda */
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-medium);
    z-index: 2;
    font-size: 1rem;
    pointer-events: none; /* Permite clicar no input através do ícone */
    transition: color 0.3s;
}

/* Estilo Base do Input */
.input-with-icon input {
    width: 100%;
    height: 50px; /* Altura fixa para melhor toque no mobile */
    padding: 0 45px; /* Espaço igual na esq e dir para os ícones */
    border: 1px solid var(--border-light);
    border-radius: 8px;
    font-size: 1rem; /* 16px evita zoom automático no iOS */
    transition: all 0.3s ease;
    background: #fcfcfc;
    color: var(--text-dark);
    box-shadow: inset 0 1px 2px rgba(0,0,0,0.02);
}

/* Foco no Input */
.input-with-icon input:focus {
    outline: none;
    border-color: var(--secondary);
    background: #fff;
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

.input-with-icon input:focus ~ i {
    color: var(--secondary);
}

/* Botão do Olho (Toggle Password) - Direita */
.toggle-password {
    position: absolute;
    right: 10px; /* Afastado da borda direita */
    top: 50%;
    transform: translateY(-50%);
    background: transparent;
    border: none;
    color: var(--text-medium);
    cursor: pointer;
    z-index: 3;
    transition: all 0.3s;

    /* Área de toque otimizada para mobile */
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
}

.toggle-password:hover {
    background-color: rgba(0,0,0,0.05); /* Feedback visual ao passar o mouse */
    color: var(--secondary);
}

.toggle-password i {
    font-size: 1.1rem; /* Ícone levemente maior */
}

/* Dicas e Validações */
.password-hint {
    color: var(--text-medium);
    font-size: 0.85rem;
    margin-top: 0.5rem;
    display: flex;
    align-items: center;
    gap: 5px;
}

.form-actions {
    margin-top: 2.5rem;
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

/* Botões */
.btn {
    padding: 0.8rem 1.8rem;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    border: none;
    font-size: 0.95rem;
}

.btn-primary {
    background: var(--secondary);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(122, 4, 235, 0.3);
}

.btn-secondary {
    background: #e1e5eb;
    color: var(--text-dark);
}

.btn-secondary:hover {
    background: #d1d5db;
}

.btn-outline {
    background: transparent;
    border: 1px solid var(--border-light);
    color: var(--danger);
}

.btn-outline:hover {
    background: #fff5f5;
    border-color: var(--danger);
}

/* Loading Spinner para Botão */
.btn-loading {
    position: relative;
    color: transparent !important;
    pointer-events: none;
}

.btn-loading::after {
    content: "";
    position: absolute;
    width: 20px;
    height: 20px;
    top: 50%;
    left: 50%;
    margin-left: -10px;
    margin-top: -10px;
    border: 2px solid rgba(255,255,255,0.3);
    border-radius: 50%;
    border-top-color: white;
    animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

/* =======================
   TOASTS (Notificações Glass)
   ======================= */
.toast-container {
    position: fixed;
    top: 20px;
    right: 20px;
    z-index: 9999;
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.toast {
    background: white;
    min-width: 300px;
    max-width: 400px;
    border-radius: 8px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.15);
    display: flex;
    align-items: center;
    padding: 1rem;
    gap: 12px;
    position: relative;
    overflow: hidden;
    transform: translateX(120%);
    opacity: 0;
    transition: all 0.4s cubic-bezier(0.68, -0.55, 0.27, 1.55);
}

.toast.show { transform: translateX(0); opacity: 1; }
.toast.hide { transform: translateX(120%); opacity: 0; }

.toast::before {
    content: '';
    position: absolute;
    left: 0; top: 0; bottom: 0; width: 5px;
}

.toast-success::before { background: var(--success); }
.toast-error::before { background: var(--danger); }
.toast-warning::before { background: var(--warning); }

.toast-icon { font-size: 1.2rem; flex-shrink: 0; }
.toast-success .toast-icon { color: var(--success); }
.toast-error .toast-icon { color: var(--danger); }
.toast-warning .toast-icon { color: var(--warning); }

.toast-content { flex-grow: 1; }
.toast-title { font-weight: 700; font-size: 0.95rem; color: var(--primary-dark); margin-bottom: 2px; }
.toast-message { font-size: 0.85rem; color: var(--text-medium); line-height: 1.3; }

.toast-close { background: none; border: none; color: #999; cursor: pointer; font-size: 1rem; padding: 5px; }
.toast-close:hover { color: var(--primary-dark); }

/* =======================
   MODAL DE CONFIRMAÇÃO
   ======================= */
.confirm-modal {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(16, 23, 40, 0.7);
    backdrop-filter: blur(4px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 10000;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.confirm-modal.active { opacity: 1; visibility: visible; }

.confirm-content {
    background: white;
    padding: 2rem;
    border-radius: 16px;
    max-width: 400px;
    width: 90%;
    text-align: center;
    box-shadow: 0 20px 60px rgba(0,0,0,0.3);
    transform: translateY(20px);
    transition: transform 0.3s;
}

.confirm-modal.active .confirm-content { transform: translateY(0); }

.confirm-icon {
    width: 70px; height: 70px;
    background: rgba(244, 67, 54, 0.1);
    color: var(--danger);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    margin: 0 auto 1.5rem;
}

.confirm-title { font-size: 1.4rem; color: var(--primary-dark); margin-bottom: 0.5rem; }
.confirm-text { color: var(--text-medium); margin-bottom: 1.5rem; line-height: 1.5; }

.confirm-actions { display: flex; gap: 1rem; justify-content: center; }
.confirm-btn { padding: 0.8rem 1.5rem; border-radius: 8px; border: none; font-weight: 600; cursor: pointer; flex: 1; transition: 0.3s; }
.confirm-btn-cancel { background: #f0f2f5; color: var(--text-dark); }
.confirm-btn-cancel:hover { background: #e1e5eb; }
.confirm-btn-delete { background: var(--danger); color: white; }
.confirm-btn-delete:hover { background: #d32f2f; box-shadow: 0 4px 12px rgba(244, 67, 54, 0.3); }

/* =======================
   Responsividade Avançada (CORRIGIDA)
   ======================= */

/* Tablets e Celulares Grandes (até 768px) */
@media (max-width: 768px) {
    /* Cabeçalho: Centraliza título e botão voltar */
    .profile-header {
        flex-direction: column;
        align-items: center; /* Centraliza horizontalmente */
        text-align: center;
        gap: 1rem;
    }

    /* Seção da Foto: Centraliza a imagem e os botões */
    .photo-upload {
        flex-direction: column;
        align-items: center; /* Garante que a foto fique no meio */
        justify-content: center;
        text-align: center;
        gap: 1.5rem;
    }

    .photo-preview {
        margin: 0 auto; /* Força margem automática lateral */
    }

    .upload-controls {
        width: 100%;
        align-items: center; /* Centraliza os botões dentro da div */
    }

    /* Card e Layout */
    .profile-card {
        padding: 1.5rem;
    }

    .form-row {
        flex-direction: column;
        gap: 0;
    }

    .setting-item {
        flex-direction: column;
        align-items: flex-start;
        text-align: left;
    }

    /* Botões esticados para facilitar o toque */
    .upload-controls .btn {
        width: 100%;
        max-width: 300px; /* Evita que fiquem gigantes em tablets */
    }
}

/* Celulares Pequenos (até 576px) */
@media (max-width: 576px) {
    .profile-header h1 {
        font-size: 1.5rem;
    }

    .profile-card {
        padding: 1.2rem;
        border-radius: 0; /* Remove borda arredondada para ganhar espaço */
        box-shadow: none; /* Remove sombra para visual mais limpo no mobile */
        background: transparent;
    }

    /* Formulários */
    .form-actions {
        flex-direction: column;
        gap: 1rem;
    }

    .form-actions .btn {
        width: 100%;
        height: 50px; /* Botão mais alto para toque */
        font-size: 1rem;
    }

    /* Garante que o input não quebre o layout e fonte legível */
    .input-with-icon input {
        font-size: 16px; /* Evita zoom automático no iOS */
        padding-left: 45px; /* Espaço para ícone */
        padding-right: 45px; /* Espaço para olho */
    }

    /* Ajuste fino nos ícones dos inputs */
    .input-with-icon i.fas:not(.fa-eye):not(.fa-eye-slash) {
        left: 15px;
    }

    .toggle-password {
        right: 5px;
        width: 45px; /* Área de toque maior */
        height: 100%; /* Altura total do input */
        display: flex;
        align-items: center;
        justify-content: center;
        top: 0;
        transform: none;
    }
}

/* Telas Muito Pequenas (até 480px) */
@media (max-width: 480px) {
    .photo-preview {
        width: 120px;
        height: 120px;
    }

    .upload-controls {
        min-width: auto;
        width: 100%;
    }

    .upload-controls .btn {
        max-width: 100%; /* Ocupa toda a tela */
    }
}

