import pool from "../config/db.js";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import bcrypt from "bcrypt";

// === 1. DEFINIÇÃO DE CAMINHOS ABSOLUTOS ===
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename); // .../main/back-end/controllers
const BACKEND_ROOT = path.join(__dirname, '..'); // .../main/back-end

// ==========================================

/**
 * ==========================================
 * 📸 ATUALIZAR / ENVIAR FOTO DE PERFIL
 * ==========================================
 */
/**
 * ==========================================
 * 📸 ATUALIZAR / ENVIAR FOTO DE PERFIL (CORRIGIDA)
 * ==========================================
 */
export const atualizarFotoPerfil = async (req, res) => {
  try {
    const userId = req.user.id; 
    const fotoPath = `/uploads/perfis/${req.file.filename}`;

    // 1️⃣ Busca a imagem anterior ativa
    // ... (o código do banco é o mesmo)
    const oldImagesResult = await pool.query(
      "SELECT caminho_arquivo FROM imagens_perfil WHERE usuario_id = $1 AND ativo = TRUE",
      [userId]
    );
    const oldImages = oldImagesResult.rows;

    // 2️⃣ Desativa imagens antigas
    await pool.query("UPDATE imagens_perfil SET ativo = FALSE WHERE usuario_id = $1", [userId]);

    // 3️⃣ Insere a nova imagem no banco
    await pool.query(
      "INSERT INTO imagens_perfil (usuario_id, caminho_arquivo, ativo) VALUES ($1, $2, TRUE)",
      [userId, fotoPath]
    );

    // 4️⃣ Remove o arquivo antigo do disco (AGORA CORRIGIDO)
    if (oldImages.length > 0) {
      const dbPath = oldImages[0].caminho_arquivo;
      // Remove a barra inicial (/) e junta com a raiz do backend
      const oldFile = path.join(BACKEND_ROOT, dbPath.substring(1)); // CORREÇÃO APLICADA AQUI

      fs.unlink(oldFile, (err) => {
        if (err) console.warn("⚠️ Não foi possível excluir a imagem antiga:", err.message);
      });
    }

    res.json({
      success: true,
      message: "Foto de perfil atualizada com sucesso!",
      fotoUrl: fotoPath,
    });
  } catch (err) {
    console.error("❌ Erro ao salvar foto de perfil:", err);
    res.status(500).json({ success: false, message: "Erro interno no servidor." });
  }
};

/**
 * ==========================================
 * 🧠 OBTER FOTO DE PERFIL DO USUÁRIO
 * ==========================================
 */
export const obterFotoPerfil = async (req, res) => {
  try {
    const result = await pool.query(
      "SELECT caminho_arquivo FROM imagens_perfil WHERE usuario_id = $1 AND ativo = TRUE LIMIT 1",
      [req.user.id]
    );

    const rows = result.rows;

    if (rows.length === 0) {
      return res.json({ fotoUrl: "/uploads/perfis/default-avatar.png" });
    }

    res.json({ fotoUrl: rows[0].caminho_arquivo });
  } catch (err) {
    console.error("❌ Erro ao buscar foto de perfil:", err);
    res.status(500).json({ message: "Erro ao buscar foto de perfil." });
  }
};

/**
 * ==========================================
 * 🗑️ REMOVER FOTO DE PERFIL
 * ==========================================
 */

/**
 * ==========================================
 * 🗑️ REMOVER FOTO DE PERFIL (CORRIGIDA - AGORA COM BACKEND_ROOT DEFINIDO)
 * ==========================================
 */
export const removerFotoPerfil = async (req, res) => {
  try {
    const userId = req.user.id;

    const result = await pool.query(
      "SELECT caminho_arquivo FROM imagens_perfil WHERE usuario_id = $1 AND ativo = TRUE",
      [userId]
    );
    const rows = result.rows;

    await pool.query("UPDATE imagens_perfil SET ativo = FALSE WHERE usuario_id = $1", [userId]);

    if (rows.length > 0) {
      const dbPath = rows[0].caminho_arquivo;

      // **A CORREÇÃO AGORA FUNCIONA** porque BACKEND_ROOT está definido no topo.
      const filePath = path.join(BACKEND_ROOT, dbPath.substring(1));

      fs.unlink(filePath, (err) => {
        if (err) {
          console.warn("⚠️ Não foi possível excluir a imagem:", err.message);
          console.warn("Caminho de exclusão tentado:", filePath);
        }
      });
    }

    res.json({ success: true, message: "Foto de perfil removida com sucesso!" });
  } catch (err) {
    console.error("❌ Erro ao remover foto de perfil:", err);
    res.status(500).json({ success: false, message: "Erro ao remover foto." });
  }
};

// ==========================================
// 🔐 ALTERAR SENHA DO USUÁRIO LOGADO
// ==========================================
export const alterarSenha = async (req, res) => {
  try {
    const userId = req.user.id;
    const { senhaAtual, novaSenha } = req.body;

    if (!senhaAtual || !novaSenha) {
      return res.status(400).json({ success: false, message: "Campos obrigatórios não enviados." });
    }

    // 1️⃣ Busca a senha hash atual do banco
    const result = await pool.query("SELECT senha_hash FROM users WHERE id = $1", [userId]);
    if (result.rowCount === 0) {
      return res.status(404).json({ success: false, message: "Usuário não encontrado." });
    }

    const senhaHashAtual = result.rows[0].senha_hash;

    // 2️⃣ Verifica se a senha atual está correta
    const senhaConfere = await bcrypt.compare(senhaAtual, senhaHashAtual);
    if (!senhaConfere) {
      return res.status(401).json({ success: false, message: "Senha atual incorreta." });
    }

    // 3️⃣ Gera hash da nova senha
    const novaSenhaHash = await bcrypt.hash(novaSenha, 10);

    // 4️⃣ Atualiza no banco
    await pool.query("UPDATE users SET senha_hash = $1 WHERE id = $2", [novaSenhaHash, userId]);

    res.json({ success: true, message: "Senha alterada com sucesso!" });
  } catch (err) {
    console.error("❌ Erro ao alterar senha:", err);
    res.status(500).json({ success: false, message: "Erro interno no servidor." });
  }
};

main/front-end/assets/css/creditos.css.content:
/* =======================
   Página de Créditos - OTIMIZADO
   ======================= */
/* Botão de fechar */
.close-btn {
    font-size: 1.5rem;
    color: var(--text-light);
    text-decoration: none; 
    background: transparent;
    border: none;
    cursor: pointer;
    transition: transform 0.2s, color 0.2s;
}

.close-btn:hover {
    color: var(--accent);
    transform: scale(1.2);
}

.creditos-container {
    display: flex;
    justify-content: center;
    padding: clamp(1rem, 4vw, 2rem);
    min-height: calc(100vh - 140px);
    align-items: flex-start;
}

.creditos-content {
    max-width: 1200px;
    width: 100%;
    background: rgba(16, 23, 40, 0.9);
    backdrop-filter: blur(15px);
    border-radius: 20px;
    padding: clamp(1.5rem, 4vw, 2.5rem);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.15);
}

.creditos-scrollable {
    max-height: 70vh;
    overflow-y: auto;
    padding-right: 1rem;
    scroll-behavior: smooth;
}

/* Scrollbar personalizada - COMPATÍVEL */
.creditos-scrollable::-webkit-scrollbar {
    width: 6px;
}

.creditos-scrollable::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 10px;
}

.creditos-scrollable::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, var(--secondary) 0%, var(--accent) 100%);
    border-radius: 10px;
}

.creditos-scrollable::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, var(--accent) 0%, var(--secondary) 100%);
}

/* Firefox */
.creditos-scrollable {
    scrollbar-width: thin;
    scrollbar-color: var(--secondary) rgba(255, 255, 255, 0.05);
}

.creditos-title {
    font-size: clamp(1.8rem, 5vw, 2.5rem);
    font-weight: 700;
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    margin-bottom: 2rem;
    text-align: center;
    position: relative;
    padding-bottom: 1rem;
    line-height: 1.2;
}

.creditos-title::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 25%;
    width: 50%;
    height: 3px;
    background: var(--gradient);
    border-radius: 3px;
}

.creditos-section h2 {
    font-size: clamp(1.4rem, 3vw, 1.8rem);
    color: var(--text-light);
    margin-bottom: 1.5rem;
    position: relative;
    padding-left: 1.5rem;
    font-weight: 600;
}

.creditos-section h2::before {
    content: '•';
    color: var(--accent);
    position: absolute;
    left: 0;
    font-size: 1.8rem;
    line-height: 1;
}

/* Grid de Créditos - RESPONSIVO */
.creditos-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));
    gap: 1.25rem;
    margin-bottom: 2.5rem;
}

.credito-card {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(10px);
    border-radius: 15px;
    padding: 1.25rem;
    display: flex;
    gap: 1.25rem;
    align-items: flex-start;
    transition: all 0.3s ease;
    border: 1px solid rgba(255, 255, 255, 0.1);
    opacity: 0;
    transform: translateY(20px);
    animation: fadeInUp 0.6s ease forwards;
}

@keyframes fadeInUp {
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.credito-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
    border-color: rgba(122, 4, 235, 0.3);
}

.credito-image {
    flex-shrink: 0;
    width: clamp(60px, 15vw, 80px);
    height: clamp(60px, 15vw, 80px);
    border-radius: 10px;
    overflow: hidden;
    border: 2px solid var(--secondary);
}

.credito-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.credito-card:hover .credito-image img {
    transform: scale(1.05);
}

.credito-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient);
}

.icon-placeholder {
    font-size: clamp(1.5rem, 4vw, 2rem);
    color: var(--text-light);
}

.credito-info {
    flex: 1;
    min-width: 0; /* Permite que o texto quebre corretamente */
}

.credito-info h3 {
    font-size: clamp(1rem, 2.5vw, 1.2rem);
    color: var(--text-light);
    margin-bottom: 0.5rem;
    line-height: 1.3;
    word-wrap: break-word;
}

.credito-info p {
    font-size: clamp(0.8rem, 2vw, 0.9rem);
    line-height: 1.4;
    margin-bottom: 0.25rem;
    color: rgba(255, 255, 255, 0.8);
    word-break: break-word;
}

.credito-info strong {
    color: var(--accent);
    font-weight: 600;
}

/* Seção Agradecimentos */
.agradecimentos-section {
    padding-top: 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.agradecimentos-section h2 {
    font-size: clamp(1.4rem, 3vw, 1.8rem);
    color: var(--text-light);
    margin-bottom: 1.5rem;
    position: relative;
    padding-left: 1.5rem;
    font-weight: 600;
}

.agradecimentos-section h2::before {
    content: '•';
    color: var(--accent);
    position: absolute;
    left: 0;
    font-size: 1.8rem;
    line-height: 1;
}

.agradecimentos-section p {
    font-size: clamp(0.9rem, 2vw, 1rem);
    line-height: 1.6;
    margin-bottom: 1rem;
    color: rgba(255, 255, 255, 0.85);
}

.agradecimentos-section em {
    color: rgba(255, 255, 255, 0.7);
    font-style: italic;
}

/* =======================
   Responsividade Avançada
   ======================= */
@media (max-width: 768px) {
    .creditos-container {
        padding: 1rem;
        min-height: calc(100vh - 120px);
    }

    .creditos-scrollable {
        max-height: 65vh;
        padding-right: 0.5rem;
    }

    .creditos-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .credito-card {
        flex-direction: column;
        text-align: center; /* Centraliza TODO o conteúdo */
        gap: 1rem;
        padding: 1.5rem;
        align-items: center; /* Centraliza horizontalmente */
    }

    .credito-image {
        width: 80px;
        height: 80px;
        margin: 0 auto;
    }

    /* GARANTIR que todo o texto fique centralizado */
    .credito-info {
        text-align: center;
        width: 100%; /* Ocupa toda a largura */
    }

    .credito-info h3,
    .credito-info p {
        text-align: center; /* Força centralização */
    }

    .creditos-title::after {
        left: 20%;
        width: 60%;
    }
}

@media (max-width: 480px) {
    .creditos-container {
        padding: 0.75rem;
    }

    .creditos-content {
        padding: 1.25rem;
        border-radius: 15px;
    }

    .creditos-scrollable {
        max-height: 60vh;
    }

    .creditos-section h2,
    .agradecimentos-section h2 {
        font-size: 1.3rem;
        padding-left: 1rem;
        text-align: center; /* Centraliza também os h2 */
    }

    .creditos-section h2::before,
    .agradecimentos-section h2::before {
        left: -0.25rem;
        font-size: 1.5rem;
    }

    .credito-card {
        padding: 1.25rem;
        text-align: center; /* Reforça centralização */
    }

    .credito-image {
        width: 70px;
        height: 70px;
    }

    /* GARANTIR centralização total */
    .credito-info {
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .credito-info h3 {
        text-align: center;
        width: 100%;
    }

    .credito-info p {
        text-align: center;
        width: 100%;
    }

    .creditos-title::after {
        left: 15%;
        width: 70%;
    }
}

@media (max-width: 360px) {
    .creditos-content {
        padding: 1rem;
    }

    .creditos-title {
        font-size: 1.6rem;
    }

    .creditos-section h2,
    .agradecimentos-section h2 {
        font-size: 1.2rem;
    }

    .credito-info h3 {
        font-size: 1.1rem;
    }
}

/* Animações escalonadas para os cards */
.credito-card:nth-child(1) { animation-delay: 0.1s; }
.credito-card:nth-child(2) { animation-delay: 0.2s; }
.credito-card:nth-child(3) { animation-delay: 0.3s; }
.credito-card:nth-child(4) { animation-delay: 0.4s; }
.credito-card:nth-child(5) { animation-delay: 0.5s; }
.credito-card:nth-child(6) { animation-delay: 0.6s; }
.credito-card:nth-child(7) { animation-delay: 0.7s; }

/* Melhorias de Acessibilidade */
@media (prefers-reduced-motion: reduce) {
    .credito-card {
        animation: none;
        opacity: 1;
        transform: none;
        transition: none;
    }

    .credito-card:hover {
        transform: none;
    }

    .creditos-scrollable {
        scroll-behavior: auto;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
    .creditos-content {
        background: var(--primary-dark);
        border: 2px solid var(--text-light);
    }

    .credito-card {
        border: 2px solid var(--text-light);
    }

    .credito-info p {
        color: var(--text-light);
    }
}

