/* =======================
   Gerenciar Ordens - Admin
   ======================= */

.page-header {
    margin-bottom: 2rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid var(--border-light);
}

.page-header h1 {
    font-size: 2rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 0.5rem;
}

.page-header h1 i {
    color: var(--secondary);
}

.page-header p {
    color: var(--text-medium);
    font-size: 1.1rem;
}

/* =======================
   Filtros - PADRONIZADO
   ======================= */

.filters-section {
