}

.stat-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
}

.stat-icon {
    width: 50px;
    height: 50px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
}

.stat-icon.pending {
    background: rgba(255, 152, 0, 0.1);
    color: #FF9800;
}

.stat-icon.in-progress {
    background: rgba(33, 150, 243, 0.1);
    color: #2196F3;
}

.stat-icon.completed {
    background: rgba(76, 175, 80, 0.1);
    color: #4CAF50;
}

.stat-icon.total {
    background: rgba(122, 4, 235, 0.1);
    color: var(--secondary);
}

.stat-info h3 {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary-dark);
    margin-bottom: 0.2rem;
}

.stat-info p {
    color: var(--text-medium);
    font-size: 0.9rem;
    margin: 0;
}

/* =======================
   Tabela - PADRONIZADO
   ======================= */

.orders-container {
    background: white;
    border-radius: 10px;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    overflow: hidden;
}

.table-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--border-light);
}

.table-header h3 {
    font-size: 1.3rem;
    color: var(--primary-dark);
    margin: 0;
}

.table-actions {
    display: flex;
    gap: 1rem;
}

.table-responsive {
    overflow-x: auto;
}

.orders-table {
    width: 100%;
    border-collapse: collapse;
}

.orders-table th {
    background: #f8f9fa;
    padding: 1rem;
    text-align: left;
    font-weight: 600;
    color: var(--primary-dark);
    border-bottom: 1px solid var(--border-light);
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.orders-table td {
    padding: 1rem;
    border-bottom: 1px solid var(--border-light);
    font-size: 0.95rem;
}

.orders-table tbody tr {
    transition: all 0.3s;
}

.orders-table tbody tr:hover {
    background: #f8f9fa;
}

.orders-table tbody tr:last-child td {
    border-bottom: none;
}

/* Status na tabela - PADRONIZADO */
.status-badge {
    padding: 0.4rem 0.8rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}

.status-badge.pending {
    background: rgba(255, 152, 0, 0.1);
    color: #FF9800;
}

.status-badge.in-progress {
    background: rgba(33, 150, 243, 0.1);
    color: #2196F3;
}

.status-badge.completed {
    background: rgba(76, 175, 80, 0.1);
    color: #4CAF50;
}

.status-badge.not-completed {
    background: rgba(244, 67, 54, 0.1);
    color: #F44336;
}

/* Ações na tabela - PADRONIZADO */
.actions-cell {
    display: flex;
    gap: 0.5rem;
}

.btn-table {
    padding: 0.5rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.btn-table.view {
    background: rgba(122, 4, 235, 0.1);
    color: var(--secondary);
}

.btn-table.edit {
    background: rgba(33, 150, 243, 0.1);
    color: #2196F3;
}

.btn-table.delete {
    background: rgba(244, 67, 54, 0.1);
    color: #F44336;
}

.btn-table:hover {
    transform: scale(1.1);
}

.btn-table.view:hover {
    background: var(--secondary);
    color: white;
}

.btn-table.edit:hover {
    background: #2196F3;
    color: white;
}

.btn-table.delete:hover {
    background: #F44336;
    color: white;
}

/* =======================
   Paginação - PADRONIZADO
   ======================= */

.pagination {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    padding: 1.5rem;
    border-top: 1px solid var(--border-light);
}

.pagination-btn {
    width: 40px;
    height: 40px;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    background: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 500;
    transition: all 0.3s;
}

.pagination-btn.active {
    background: var(--secondary);
    color: white;
    border-color: var(--secondary);
}

.pagination-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination-btn:not(.active):not(:disabled):hover {
    background: #f0f2f5;
    border-color: var(--secondary);
}

/* =======================
   Modal - PADRONIZADO
   ======================= */

.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(5px);
    z-index: 1000;
    justify-content: center;
    align-items: center;
}

.modal.active {
    display: flex;
}

.modal-content {
    background: white;
    border-radius: 10px;
    width: 90%;
    max-width: 700px;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-header {
    padding: 1.5rem;
    border-bottom: 1px solid var(--border-light);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.modal-header h3 {
    font-size: 1.4rem;
    color: var(--primary-dark);
    margin: 0;
}

.modal-close {
    background: none;
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    color: var(--text-medium);
    transition: color 0.3s;
}

.modal-close:hover {
    color: var(--accent);
}

.modal-body {
    padding: 1.5rem;
}

.modal-footer {
    padding: 1rem 1.5rem;
    border-top: 1px solid var(--border-light);
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

/* Grid de detalhes no modal */
.detail-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
}

.detail-item {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.detail-item.full-width {
    grid-column: 1 / -1;
}

.detail-item label {
    font-weight: 600;
    color: var(--primary-dark);
    font-size: 0.9rem;
}

.detail-item span,
.detail-item p {
    color: var(--text-medium);
    margin: 0;
}

.detail-item p {
    line-height: 1.5;
}

/* =======================
   Botões - PADRONIZADO
   ======================= */

.btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    border: none;
    font-size: 0.95rem;
}

.btn-primary {
    background: var(--secondary);
    color: white;
}

.btn-primary:hover {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.btn-secondary {
    background: #f0f2f5;
    color: var(--text-dark);
}

.btn-secondary:hover {
    background: #e6e9f0;
}

/* =======================
   Responsividade - OTIMIZADA
   ======================= */

@media (max-width: 1200px) {
    .filters-container {
        gap: 1rem;
    }

    .search-box {
        min-width: 250px;
    }

    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 992px) {
    .page-header h1 {
        font-size: clamp(1.5rem, 4vw, 2rem);
    }

    .filters-container {
        flex-direction: column;
        align-items: stretch;
    }

    .filter-group {
        width: 100%;
        justify-content: space-between;
    }

    .search-box {
        min-width: auto;
        flex: 1;
    }

    .filters-container select {
        min-width: 150px;
        flex: 1;
    }
}

@media (max-width: 768px) {
    .admin-content {
        padding: 1rem;
    }

    .filters-section {
        padding: 1.25rem;
    }

    .filter-group {
        flex-direction: column;
        gap: 0.75rem;
    }

    .search-box,
    .filters-container select {
        width: 100%;
        min-width: auto;
    }

    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 0.75rem;
    }

    .stat-card {
        padding: 0.875rem;
        gap: 0.75rem;
    }

    .stat-icon {
        width: 40px;
        height: 40px;
        font-size: 1.1rem;
    }

    .stat-info h3 {
        font-size: 1.3rem;
    }

    .stat-info p {
        font-size: 0.85rem;
    }

    .table-header {
        flex-direction: column;
        gap: 1rem;
        align-items: flex-start;
        padding: 1.25rem;
    }

    .table-actions {
        width: 100%;
        justify-content: flex-end;
    }

    .orders-table {
        font-size: 0.85rem;
    }

    .orders-table th,
    .orders-table td {
        padding: 0.75rem 0.5rem;
        white-space: nowrap;
    }

    .orders-table th:nth-child(4), /* Descrição */
    .orders-table td:nth-child(4) {
        max-width: 150px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .status-badge {
        font-size: 0.75rem;
        padding: 0.3rem 0.6rem;
    }

    .actions-cell {
        flex-direction: row;
        gap: 0.3rem;
    }

    .btn-table {
        width: 35px;
        height: 35px;
        font-size: 0.8rem;
    }

    .modal-content {
        width: 95%;
        margin: 1rem;
        max-width: none;
    }

    .detail-grid {
        grid-template-columns: 1fr;
        gap: 0.75rem;
    }

    .detail-item {
        gap: 0.3rem;
    }

    .detail-item label {
        font-size: 0.85rem;
    }

    .detail-item span,
    .detail-item p {
        font-size: 0.9rem;
    }
}

@media (max-width: 576px) {
    .filters-section {
        padding: 1rem;
        border-radius: 8px;
    }

    .stats-cards {
        grid-template-columns: 1fr;
    }

    .stat-card {
        flex-direction: row;
        text-align: left;
        justify-content: flex-start;
    }

    .table-header h3 {
        font-size: 1.1rem;
    }

    .btn {
        padding: 0.7rem 1rem;
        font-size: 0.9rem;
    }

    /* Otimização da tabela para mobile */
    .orders-table {
        min-width: 800px; /* Força scroll horizontal */
    }

    .orders-table thead th:nth-child(2), /* Solicitante */
    .orders-table thead th:nth-child(5), /* Data */
    .orders-table thead th:nth-child(6) { /* Técnico */
        display: none;
    }

    .orders-table tbody td:nth-child(2),
    .orders-table tbody td:nth-child(5),
    .orders-table tbody td:nth-child(6) {
        display: none;
    }

    .orders-table th,
    .orders-table td {
        padding: 0.6rem 0.4rem;
    }

    .pagination {
        padding: 1rem;
        gap: 0.3rem;
    }

    .pagination-btn {
        width: 35px;
        height: 35px;
        font-size: 0.85rem;
    }

    .modal-content {
        width: 98%;
        margin: 0.5rem;
    }

    .modal-header,
    .modal-body,
    .modal-footer {
        padding: 1rem;
    }
}

@media (max-width: 480px) {
    .filter-group:last-child {
        flex-direction: row;
        justify-content: space-between;
    }

    .btn {
        flex: 1;
        justify-content: center;
    }

    .table-actions {
        flex-direction: column;
        gap: 0.5rem;
    }

    .table-actions .btn {
        width: 100%;
    }

    .orders-table {
        min-width: 700px;
    }

    /* Esconde mais colunas em telas muito pequenas */
    .orders-table thead th:nth-child(3), /* Local */
    .orders-table tbody td:nth-child(3) {
        display: none;
    }

    .actions-cell {
        flex-direction: column;
        gap: 0.2rem;
    }

    .btn-table {
        width: 100%;
        height: 32px;
    }

    .modal-content {
        border-radius: 8px;
    }

    .alert-modal {
        padding: 1.25rem;
    }

    .alert-title {
        font-size: 1.3rem;
    }

    .alert-message {
        font-size: 0.9rem;
    }

    .alert-actions {
        flex-direction: column;
    }

    .alert-btn {
        width: 100%;
    }
}

@media (max-width: 360px) {
    .admin-content {
        padding: 0.75rem;
    }

    .stat-card {
        padding: 0.75rem;
    }

    .stat-icon {
        width: 35px;
        height: 35px;
        font-size: 1rem;
    }

    .stat-info h3 {
        font-size: 1.2rem;
    }

    .orders-table {
        min-width: 650px;
        font-size: 0.8rem;
    }

    .pagination-btn {
        width: 32px;
        height: 32px;
        font-size: 0.8rem;
    }
}

/* =======================
   Melhorias de Usabilidade Mobile
   ======================= */

/* Scroll horizontal suave para a tabela */
.table-responsive {
    -webkit-overflow-scrolling: touch;
    scroll-behavior: smooth;
}

/* Indicador visual de scroll horizontal */
.table-responsive::-webkit-scrollbar {
    height: 6px;
}

.table-responsive::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 3px;
}

.table-responsive::-webkit-scrollbar-thumb {
    background: var(--secondary);
    border-radius: 3px;
}

.table-responsive::-webkit-scrollbar-thumb:hover {
    background: var(--accent);
}

/* Touch-friendly para botões de ação */
.btn-table {
    min-height: 44px;
    min-width: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Feedback visual para toques */
.btn-table:active {
    transform: scale(0.95);
}

/* Loading overlay mobile */
@media (max-width: 768px) {
    #loading-overlay .spinner {
        width: 40px;
        height: 40px;
        border-width: 3px;
    }
}

/* Ajustes para formulário de edição em mobile */
@media (max-width: 768px) {
    .form-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .form-group input,
    .form-group select,
    .form-group textarea {
        padding: 0.75rem;
        font-size: 16px; /* Previne zoom no iOS */
    }
}

/* Melhorias para lista de anexos em mobile */
@media (max-width: 768px) {
    .anexo-item {
        padding: 0.75rem;
        min-height: 44px;
    }

    .anexo-item i {
        font-size: 1rem;
    }
}

/* =======================
   High Contrast Mode Mobile
   ======================= */
@media (max-width: 768px) and (prefers-contrast: high) {
    .orders-table {
        border: 2px solid #000;
    }

    .orders-table th {
        background: #000;
        color: #fff;
    }

    .table-responsive::-webkit-scrollbar-thumb {
        background: #000;
    }
}

/* =======================
   Reduced Motion Support
   ======================= */
@media (prefers-reduced-motion: reduce) {
    .table-responsive {
        scroll-behavior: auto;
    }

    .btn-table,
    .stat-card,
    .action-card {
        transition: none;
    }

    .btn-table:hover,
    .stat-card:hover {
        transform: none;
    }
}

/* =======================
   Estado Vazio Melhorado para Mobile
   ======================= */
@media (max-width: 768px) {
    .orders-table tbody td[colspan] {
        padding: 2rem 1rem;
        text-align: center;
    }

    .orders-table tbody td[colspan] i {
        font-size: 1.5rem;
        margin-bottom: 0.5rem;
    }
}


/* =======================
   ESTILOS ADICIONAIS - Edição e Anexos
   Adicione isso ao final do ordens-admin.css
   ======================= */

/* Formulário de Edição */
.form-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.form-group.full-width {
    grid-column: 1 / -1;
}

.form-group label {
    font-weight: 600;
    color: var(--primary-dark);
    font-size: 0.9rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    padding: 0.8rem;
    border: 1px solid var(--border-light);
    border-radius: 8px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: all 0.3s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--secondary);
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 80px;
}

/* Lista de Anexos */
.anexos-list {
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
    margin-top: 0.5rem;
}

.anexo-item {
    display: flex;
    align-items: center;
    gap: 0.8rem;
    padding: 0.8rem 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    text-decoration: none;
    color: var(--text-dark);
    transition: all 0.3s;
    border: 1px solid var(--border-light);
}

.anexo-item:hover {
    background: var(--secondary);
    color: white;
    transform: translateX(5px);
    border-color: var(--secondary);
}

.anexo-item i {
    font-size: 1.1rem;
    color: var(--secondary);
}

.anexo-item:hover i {
    color: white;
}

/* Loading Overlay */
#loading-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.7);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;
}

.spinner {
    width: 50px;
    height: 50px;
    border: 4px solid rgba(255, 255, 255, 0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Sistema de Alertas Customizado */
.alert-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(5px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 10000;
    opacity: 0;
    transition: opacity 0.3s;
}

.alert-overlay.visible {
    opacity: 1;
}

.alert-modal {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    max-width: 500px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    text-align: center;
    animation: slideDown 0.3s ease-out;
}

@keyframes slideDown {
    from {
        transform: translateY(-50px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

.alert-icon {
    width: 80px;
    height: 80px;
    margin: 0 auto 1.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2.5rem;
}

.alert-overlay.alert-success .alert-icon {
    background: rgba(76, 175, 80, 0.1);
    color: #4CAF50;
}

.alert-overlay.alert-error .alert-icon {
    background: rgba(244, 67, 54, 0.1);
    color: #F44336;
}

.alert-overlay.alert-warning .alert-icon {
    background: rgba(255, 152, 0, 0.1);
    color: #FF9800;
}

.alert-overlay.alert-info .alert-icon {
    background: rgba(33, 150, 243, 0.1);
    color: #2196F3;
}

.alert-title {
    font-size: 1.5rem;
    color: var(--primary-dark);
    margin-bottom: 1rem;
}

.alert-message {
    color: var(--text-medium);
    font-size: 1rem;
    line-height: 1.6;
    margin-bottom: 1.5rem;
}

.alert-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.alert-btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    border: none;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s;
    font-size: 0.95rem;
}

.alert-btn-primary {
    background: var(--secondary);
    color: white;
}

.alert-btn-primary:hover {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.alert-btn-secondary {
    background: #f0f2f5;
    color: var(--text-dark);
}

.alert-btn-secondary:hover {
    background: #e6e9f0;
}

/* Responsividade para Formulário */
@media (max-width: 768px) {
    .form-grid {
        grid-template-columns: 1fr;
    }

    .alert-modal {
        padding: 1.5rem;
    }

    .alert-actions {
        flex-direction: column;
    }

    .alert-btn {
        width: 100%;
    }
}

main/front-end/assets/css/criar-ordem.cs.content:
/* =======================
   CRIAR ORDEM - SUPORTE
   criar-ordem.css
   ======================= */

/* =======================
   Variáveis Globais (Garantia)
   ======================= */
:root {
    --primary-bg: #ffffff;
    --secondary-bg: #f5f7fa;
    --text-dark: #101728;
    --text-medium: #555;
    --text-light: #999;
    --border-light: #e1e5eb;
    --card-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    --accent: #7a04eb;
    --secondary: #555;
    --success: #4CAF50;
    --danger: #F44336;
}

/* =======================
   Layout da Página
   ======================= */
.suporte-content {
    padding: 2rem;
    background: var(--secondary-bg);
    min-height: calc(100vh - 70px);
}

.order-header {
    margin-bottom: 3rem;
    text-align: center;
}

.order-header h1 {
    font-size: 2rem;
    color: var(--text-dark);
    margin-bottom: 0.5rem;
}

.order-header p {
    color: var(--text-medium);
    font-size: 1.1rem;
}

/* =======================
   Cards de Seleção
   ======================= */
.card-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
    max-width: 1000px;
    margin: 0 auto;
}

.card {
    background: #fff;
    border-radius: 16px;
    padding: 3rem 2rem;
    text-align: center;
    box-shadow: var(--card-shadow);
    cursor: pointer;
    transition: all 0.3s ease;
    border: 2px solid transparent;
    position: relative;
    overflow: hidden;
}

.card:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(122, 4, 235, 0.15);
    border-color: var(--accent);
}

/* Ícone do Card */
.card-icon {
    width: 80px;
    height: 80px;
    background: rgba(122, 4, 235, 0.05);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
    font-size: 2.5rem;
    color: var(--accent);
    transition: all 0.3s ease;
}

.card:hover .card-icon {
    background: var(--accent);
    color: #fff;
    transform: scale(1.1);
}

.card h2 {
    font-size: 1.5rem;
    color: var(--text-dark);
    margin-bottom: 1rem;
    font-weight: 700;
}

.card p {
    color: var(--text-medium);
    line-height: 1.6;
    font-size: 1rem;
}

/* =======================
   MODAIS (Formulários)
   ======================= */
.modal-overlay {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(16, 23, 40, 0.8);
    backdrop-filter: blur(5px);
    z-index: 2000;
    display: none; /* Controlado por JS */
    justify-content: center;
    align-items: center;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.modal-overlay.active {
    display: flex;
    opacity: 1;
}

.modal-content {
    background: #fff;
    border-radius: 16px;
    width: 90%;
    max-width: 600px;
    padding: 2.5rem;
    position: relative;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 25px 50px rgba(0,0,0,0.3);
    transform: translateY(20px);
    transition: transform 0.3s ease;
}

.modal-overlay.active .modal-content {
    transform: translateY(0);
}

.modal-content h2 {
    font-size: 1.6rem;
    color: var(--text-dark);
    margin-bottom: 2rem;
    display: flex;
    align-items: center;
    gap: 10px;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--border-light);
}

.modal-content h2 i { color: var(--accent); }

.close {
    position: absolute;
    top: 1.5rem;
    right: 1.5rem;
    font-size: 1.8rem;
    color: #999;
    cursor: pointer;
    transition: color 0.2s;
    line-height: 1;
}

.close:hover { color: var(--danger); }

/* =======================
   Estilo dos Formulários
   ======================= */
form label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 600;
    color: var(--text-dark);
    font-size: 0.95rem;
}

form label i {
    color: var(--accent);
    margin-right: 5px;
    width: 20px;
    text-align: center;
}

/* Inputs e Selects */
input, select, textarea {
    width: 100%;
    padding: 0.8rem 1rem;
    border: 1px solid var(--border-light);
    border-radius: 8px;
    font-size: 1rem;
    margin-bottom: 1.5rem;
    transition: all 0.3s;
    background: #fcfcfc;
    font-family: inherit;
}

input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: var(--accent);
    background: #fff;
    box-shadow: 0 0 0 4px rgba(122, 4, 235, 0.1);
}

/* Select com valor selecionado (Feedback Visual) */
select.selected {
    border-color: var(--accent);
    background: rgba(122, 4, 235, 0.05);
}

textarea {
    resize: vertical;
    min-height: 120px;
}

/* Botão de Enviar */
button[type="submit"] {
    background: var(--accent);
    color: #fff;
    width: 100%;
    padding: 1rem;
    font-size: 1rem;
    font-weight: 600;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 1rem;
}

button[type="submit"]:hover {
    background: #6003b0; /* Tom mais escuro */
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

/* =======================
   Upload de Arquivos
   ======================= */
.file-upload-section {
    background: #f9f9f9;
    border: 1px dashed var(--border-light);
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1.5rem;
    text-align: center;
}

.file-label {
    display: block;
    margin-bottom: 1rem;
    color: var(--text-medium);
}

.file-limit {
    font-size: 0.8rem;
    color: #999;
    font-weight: normal;
}

.file-upload-btn {
    background: #fff;
    border: 1px solid var(--accent);
    color: var(--accent);
    padding: 0.6rem 1.2rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.file-upload-btn:hover {
    background: var(--accent);
    color: #fff;
}

/* Lista de Arquivos (Preview) */
#file-list-problema {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 1rem;
    justify-content: center;
}

.file-item {
    background: #fff;
    border: 1px solid var(--border-light);
    padding: 0.5rem 0.8rem;
    border-radius: 6px;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.9rem;
    box-shadow: 0 2px 5px rgba(0,0,0,0.05);
}

.preview-thumb {
    width: 30px;
    height: 30px;
    object-fit: cover;
    border-radius: 4px;
}

.file-item .remove {
    color: var(--danger);
    cursor: pointer;
    font-weight: bold;
    margin-left: 5px;
    padding: 0 5px;
}

.file-item .remove:hover {
    background: #ffebee;
    border-radius: 50%;
}

/* =======================
   RESPONSIVIDADE
   ======================= */
@media (max-width: 768px) {
    .suporte-content {
        padding: 1.5rem 1rem;
    }

    .order-header h1 {
        font-size: 1.6rem;
    }

    .card-container {
        grid-template-columns: 1fr; /* Cards empilhados no mobile */
        gap: 1.5rem;
    }

    .card {
        padding: 2rem 1.5rem;
    }

    .modal-content {
        padding: 1.5rem;
        width: 95%;
        margin: 1rem;
    }

    .modal-content h2 {
        font-size: 1.4rem;
    }
}

