document.addEventListener('DOMContentLoaded', function() {
    // =========================
    // 1. Inicialização e Validação
    // =========================
    const token = localStorage.getItem("authToken");
    const user = JSON.parse(localStorage.getItem("currentUser"));

    // =========================
    // 2. Menu Hambúrguer e Sidebar
    // =========================
    const menuToggle = document.querySelector('.menu-toggle');
    const sidebar = document.querySelector('.sidebar');
    let overlay = document.querySelector('.overlay');

    // Cria overlay se não existir
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.className = 'overlay';
        document.body.appendChild(overlay);
    }

    if (menuToggle && sidebar) {
        menuToggle.addEventListener('click', (e) => {
            e.stopPropagation();
            sidebar.classList.toggle('active');
            overlay.classList.toggle('active');
        });

        overlay.addEventListener('click', () => {
            sidebar.classList.remove('active');
            overlay.classList.remove('active');
        });
    }

    // =========================
    // 3. Dropdown do Perfil (Corrigido)
    // =========================
    const profileAvatar = document.querySelector('.profile-avatar');
    const dropdown = document.querySelector('.dropdown-content');

    if (profileAvatar && dropdown) {
        // Alternar ao clicar na foto
        profileAvatar.addEventListener('click', (e) => {
            e.stopPropagation(); // Impede que o clique feche o menu imediatamente
            dropdown.classList.toggle('active');
        });

        // Fechar ao clicar fora
        document.addEventListener('click', (e) => {
            if (!dropdown.contains(e.target) && e.target !== profileAvatar) {
                dropdown.classList.remove('active');
            }
        });
    }

    // =========================
    // 4. Preencher Dados do Usuário
    // =========================
    const userNameEl = document.getElementById("userName");
    const userEmailEl = document.getElementById("userEmail");
    const welcomeNameEl = document.getElementById("welcomeName");

    if (user) {
        if(userNameEl) userNameEl.textContent = user.nome;
        if(userEmailEl) userEmailEl.textContent = user.email;
        if(welcomeNameEl) welcomeNameEl.textContent = user.nome;
    }

    // Logout
    const logoutBtn = document.getElementById("logout");
    if (logoutBtn) {
        logoutBtn.addEventListener("click", (e) => {
            e.preventDefault();
            localStorage.removeItem("authToken");
            localStorage.removeItem("currentUser");
            window.location.href = "../../index.html";
        });
    }

    // =========================
    // 5. Carregar Ordens (Dashboard)
    // =========================
    const recentOrdersEl = document.getElementById("recentOrders");
    const badgePendentesEl = document.getElementById("badgePendentes");

    async function fetchOrdens() {
        if (!recentOrdersEl) return;

        try {
            const res = await fetch("/api/minhas-ordens", {
                headers: { "Authorization": "Bearer " + token }
            });

            if (!res.ok) throw new Error("Erro ao buscar dados");

            const ordens = await res.json();
            renderOrdens(ordens);
        } catch (err) {
            console.error(err);
            recentOrdersEl.innerHTML = "<p>Erro ao carregar ordens recentes.</p>";
        }
    }

    function renderOrdens(ordens) {
        if (!recentOrdersEl) return;
        recentOrdersEl.innerHTML = "";

        // Atualiza Badge
        const pendentes = ordens.filter(o => o.status === "Pendente").length;
        if (badgePendentesEl) badgePendentesEl.textContent = pendentes;

        // Pega as 3 últimas
        const ultimas = ordens.slice(0, 3);

        if (ultimas.length === 0) {
            recentOrdersEl.innerHTML = "<p>Nenhuma ordem encontrada.</p>";
            return;
        }

        ultimas.forEach(o => {
            const div = document.createElement("div");
            let statusClass = "";

            switch(o.status) {
                case "Pendente": statusClass = "pendente"; break;
                case "Em Andamento": statusClass = "em-andamento"; break;
                case "Concluída": statusClass = "concluida"; break;
                default: statusClass = "";
            }

            const titulo = o.titulo || `${o.tipo_solicitacao} - ${o.local_detalhe || 'Local'}`;
            const descricao = o.descricao || "Sem descrição";

            div.className = `order-card ${statusClass}`;
            div.innerHTML = `
                <h3>${titulo}</h3>
                <p>${descricao}</p>
                <span class="status">${o.status}</span>
                <span class="date">${new Date(o.data_criacao).toLocaleDateString('pt-BR')}</span>
            `;
            recentOrdersEl.appendChild(div);
        });
    }

    fetchOrdens();
});

main/front-end/assets/css/relatorios.css.content:
/* =======================
   Relatórios - Admin
   relatorios.css
   ======================= */

/* Variáveis Globais (Garantia) */
:root {
    --primary-dark: #101728;
    --secondary: #7a04eb;
    --accent: #ff00e2;
    --text-medium: #666;
    --text-light: #999;
    --border-light: #e1e5eb;
    --success: #4CAF50;
    --danger: #F44336;
    --warning: #FF9800;
    --info: #2196F3;
}

.page-header {
    margin-bottom: 2rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid var(--border-light);
}

.page-header h1 {
    font-size: 2rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 0.5rem;
}

.page-header h1 i {
    color: var(--secondary);
}

.page-header p {
    color: var(--text-medium);
    font-size: 1.1rem;
}

/* =======================
   Filtros - PADRONIZADO
   ======================= */

.filters-section {
    background: white;
    border-radius: 10px;
    padding: 1.5rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    margin-bottom: 2rem;
}

.filters-container {
    display: flex;
    flex-wrap: wrap;
    gap: 1.5rem;
    align-items: flex-end;
}

.filter-group {
    display: flex;
    gap: 1rem;
    align-items: flex-end;
    flex-grow: 1;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    flex-grow: 1;
}

.form-group label {
    font-weight: 600;
    color: var(--primary-dark);
    font-size: 0.9rem;
}

.form-group select,
.form-group input[type="date"] {
    padding: 0.8rem 1rem;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    font-size: 0.95rem;
    transition: all 0.3s;
    width: 100%;
    background: white;
}

.form-group select:focus,
.form-group input[type="date"]:focus {
    outline: none;
    border-color: var(--secondary);
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

/* =======================
   Estatísticas
   ======================= */

.stats-section {
    background: white;
    border-radius: 10px;
    padding: 1.5rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    margin-bottom: 2rem;
}

.stats-section h3 {
    font-size: 1.3rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5rem;
}

.stat-card {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1.5rem;
    background: #f8f9fa;
    border-radius: 12px;
    transition: all 0.3s;
    border: 1px solid transparent;
}

.stat-card:hover {
    transform: translateY(-5px);
    background: white;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.08);
    border-color: var(--border-light);
}

.stat-icon {
    width: 50px;
    height: 50px;
    border-radius: 12px;
    background: rgba(122, 4, 235, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
    color: var(--secondary);
}

.stat-info h3 {
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--primary-dark);
    margin-bottom: 0.3rem;
    line-height: 1;
}

.stat-info p {
    color: var(--text-medium);
    font-size: 0.9rem;
    margin: 0;
    font-weight: 500;
}

/* =======================
   Cards de Relatórios
   ======================= */

.reports-section {
    background: white;
    border-radius: 10px;
    padding: 2rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
    margin-bottom: 3rem;
}

.section-header {
    margin-bottom: 1.5rem;
}

.section-header h3 {
    font-size: 1.3rem;
    color: var(--primary-dark);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
}

.section-header p {
    color: var(--text-medium);
    margin: 0;
}

.reports-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 1.5rem;
}

.report-card {
    background: #f8f9fa;
    border-radius: 12px;
    padding: 1.5rem;
    display: flex;
    gap: 1rem;
    transition: all 0.3s;
    border: 1px solid transparent;
    position: relative;
    overflow: hidden;
}

.report-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
    border-color: var(--secondary);
    background: white;
}

.report-icon {
    width: 50px;
    height: 50px;
    border-radius: 12px;
    background: rgba(122, 4, 235, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
    color: var(--secondary);
    flex-shrink: 0;
}

.report-content {
    flex: 1;
}

.report-content h4 {
    font-size: 1.1rem;
    color: var(--primary-dark);
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.report-content p {
    color: var(--text-medium);
    font-size: 0.9rem;
    margin-bottom: 1rem;
    line-height: 1.5;
}

.report-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    font-size: 0.8rem;
    color: var(--text-light);
}

.report-meta span {
    display: flex;
    align-items: center;
    gap: 0.3rem;
}

.report-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    justify-content: center;
}

/* =======================
   Histórico
   ======================= */

.history-section {
    background: white;
    border-radius: 10px;
    padding: 2rem;
    box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
}

.table-responsive {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.reports-history-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 800px; /* Garante estrutura no mobile */
}

.reports-history-table th {
    background: #f8f9fa;
    padding: 1rem;
    text-align: left;
    font-weight: 600;
    color: var(--primary-dark);
    border-bottom: 2px solid var(--border-light);
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.reports-history-table td {
    padding: 1rem;
    border-bottom: 1px solid var(--border-light);
    font-size: 0.95rem;
    vertical-align: middle;
}

.reports-history-table tbody tr {
    transition: background-color 0.2s;
}

.reports-history-table tbody tr:hover {
    background: #f9faff;
}

/* Ações Tabela */
.actions-cell {
    display: flex;
    gap: 0.5rem;
}

.btn-table {
    width: 35px;
    height: 35px;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.btn-table.preview { background: rgba(122, 4, 235, 0.1); color: var(--secondary); }
.btn-table.preview:hover { background: var(--secondary); color: white; }

.btn-table.download { background: rgba(76, 175, 80, 0.1); color: var(--success); }
.btn-table.download:hover { background: var(--success); color: white; }

/* =======================
   Botões
   ======================= */

.btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    border: none;
    font-size: 0.95rem;
    min-height: 44px;
}

.btn-primary {
    background: var(--secondary);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.btn-primary:disabled {
    background: #ccc;
    cursor: not-allowed;
}

.btn-secondary {
    background: #e1e5eb;
    color: var(--text-medium);
}

.btn-secondary:hover {
    background: #d1d5db;
    color: var(--primary-dark);
}

/* =======================
   ALERTAS CUSTOMIZADOS (Faltava no original)
   ======================= */

.alert-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(16, 23, 40, 0.7); /* Backdrop escuro */
    backdrop-filter: blur(4px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 10000;
    opacity: 0;
    transition: opacity 0.3s ease;
    visibility: hidden;
}

.alert-overlay.visible {
    opacity: 1;
    visibility: visible;
}

.alert-modal {
    background: white;
    padding: 2rem;
    border-radius: 16px;
    max-width: 450px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    text-align: center;
    transform: translateY(20px);
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.alert-overlay.visible .alert-modal {
    transform: translateY(0);
}

.alert-icon {
    width: 70px;
    height: 70px;
    margin: 0 auto 1.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
}

/* Cores dos Ícones de Alerta */
.alert-success .alert-icon { background: rgba(76, 175, 80, 0.1); color: var(--success); }
.alert-error .alert-icon { background: rgba(244, 67, 54, 0.1); color: var(--danger); }
.alert-warning .alert-icon { background: rgba(255, 152, 0, 0.1); color: var(--warning); }
.alert-info .alert-icon { background: rgba(33, 150, 243, 0.1); color: var(--info); }

.alert-title {
    font-size: 1.4rem;
    color: var(--primary-dark);
    margin-bottom: 0.8rem;
    font-weight: 700;
}

.alert-message {
    color: var(--text-medium);
    font-size: 1rem;
    line-height: 1.5;
    margin-bottom: 2rem;
}

.alert-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.alert-btn {
    padding: 0.8rem 2rem;
    border-radius: 8px;
    border: none;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    font-size: 0.95rem;
    min-width: 120px;
}

.alert-btn-primary { background: var(--secondary); color: white; }
.alert-btn-primary:hover { background: var(--accent); box-shadow: 0 4px 15px rgba(122, 4, 235, 0.3); }

.alert-btn-secondary { background: #f0f2f5; color: var(--text-medium); }
.alert-btn-secondary:hover { background: #e1e5eb; color: var(--text-dark); }

/* =======================
   Responsividade
   ======================= */

@media (max-width: 992px) {
    .filters-container {
        flex-direction: column;
        align-items: stretch;
    }

    .filter-group {
        width: 100%;
        flex-wrap: wrap;
    }
}

@media (max-width: 768px) {
    .page-header h1 { font-size: 1.6rem; }

    /* Ajustes na Tabela Mobile */
    .reports-history-table {
        min-width: 100%;
    }

    .reports-history-table th, 
    .reports-history-table td {
        padding: 0.8rem 0.5rem;
        font-size: 0.85rem;
    }

    /* ESCONDER Colunas menos importantes no mobile */
    .reports-history-table th:nth-child(1), .reports-history-table td:nth-child(1), /* ID */
    .reports-history-table th:nth-child(4), .reports-history-table td:nth-child(4), /* Formato */
    .reports-history-table th:nth-child(6), .reports-history-table td:nth-child(6)  /* Tamanho */
    {
        display: none;
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .reports-grid {
        grid-template-columns: 1fr;
    }

    .report-card {
        padding: 1.2rem;
    }
}

@media (max-width: 576px) {
    .stats-grid {
        grid-template-columns: 1fr;
    }

    .filter-group {
        flex-direction: column;
        align-items: stretch;
        gap: 0.8rem;
    }

    .actions-cell {
        justify-content: flex-end;
    }

    /* Ajuste no alerta mobile */
    .alert-modal {
        padding: 1.5rem;
    }

    .alert-actions {
        flex-direction: column;
    }

    .alert-btn {
        width: 100%;
    }
}

