/* =======================
   Melhorias de Acessibilidade Mobile
   ======================= */
@media (max-width: 992px) {
    .sidebar-nav a {
        padding: 1rem 1.25rem;
    }

    .sidebar-nav a i {
        font-size: 1.2rem;
        margin-right: 1rem;
    }

    .sidebar-nav a span {
        font-size: 1rem;
    }

    /* Melhor touch target para mobile */
    .menu-toggle,
    .profile-avatar,
    .sidebar-nav a {
        min-height: 44px;
    }

    .action-card {
        cursor: pointer;
    }
}

/* =======================
   Estados de Loading Mobile
   ======================= */
@media (max-width: 768px) {
    .action-card.loading {
        position: relative;
        overflow: hidden;
    }

    .action-card.loading::after {
        content: '';
        position: absolute;
        top: 0;
        left: -100%;
        width: 100%;
        height: 100%;
        background: linear-gradient(
            90deg,
            transparent,
            rgba(255, 255, 255, 0.4),
            transparent
        );
        animation: loading 1.5s infinite;
    }

    @keyframes loading {
        0% { left: -100%; }
        100% { left: 100%; }
    }
}

/* =======================
   Scroll Suave para Mobile
   ======================= */
@media (max-width: 768px) {
    .admin-content {
        scroll-behavior: smooth;
        -webkit-overflow-scrolling: touch;
    }
}

/* =======================
   High Contrast Mode Mobile
   ======================= */
@media (max-width: 768px) and (prefers-contrast: high) {
    .action-card {
        border: 2px solid #333;
    }

    .sidebar {
        border-right: 2px solid #333;
    }

    .admin-navbar {
        border-bottom: 2px solid #333;
    }
}

/* =======================
   Reduced Motion Support
   ======================= */
@media (prefers-reduced-motion: reduce) {
    .sidebar,
    .action-card,
    .stat-card,
    .menu-toggle,
    .profile-avatar {
        transition: none;
    }

    .action-card:hover,
    .stat-card:hover {
        transform: none;
    }
}

