}

.users-table tbody tr:last-child td {
    border-bottom: none;
}

/* Status na tabela */
.status-badge {
    padding: 0.4rem 0.8rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}

.status-badge.active {
    background: rgba(76, 175, 80, 0.1);
    color: #4CAF50;
}

.status-badge.inactive {
    background: rgba(158, 158, 158, 0.1);
    color: #9E9E9E;
}

/* Cargos na tabela */
.role-badge {
    padding: 0.4rem 0.8rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
}

.role-badge.professor {
    background: rgba(33, 150, 243, 0.1);
    color: #2196F3;
}

.role-badge.suporte {
    background: rgba(255, 152, 0, 0.1);
    color: #FF9800;
}

.role-badge.admin {
    background: rgba(156, 39, 176, 0.1);
    color: #9C27B0;
}

/* Ações na tabela - PADRONIZADO */
.actions-cell {
    display: flex;
    gap: 0.5rem;
}

.btn-table {
    padding: 0.5rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.btn-table.view {
    background: rgba(122, 4, 235, 0.1);
    color: var(--secondary);
}

.btn-table.edit {
    background: rgba(33, 150, 243, 0.1);
    color: #2196F3;
}

.btn-table.delete {
    background: rgba(244, 67, 54, 0.1);
    color: #F44336;
}

.btn-table:hover {
    transform: scale(1.1);
}

.btn-table.view:hover {
    background: var(--secondary);
    color: white;
}

.btn-table.edit:hover {
    background: #2196F3;
    color: white;
}

.btn-table.delete:hover {
    background: #F44336;
    color: white;
}

/* =======================
   Formulário no Modal
   ======================= */

.form-row {
    display: flex;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.form-group {
    flex: 1;
    margin-bottom: 1.5rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: var(--primary-dark);
}

.form-group input,
.form-group select {
    width: 100%;
    padding: 0.8rem 1rem;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    font-size: 0.95rem;
    transition: all 0.3s;
}

.form-group input:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--secondary);
    box-shadow: 0 0 0 3px rgba(122, 4, 235, 0.1);
}

.form-hint {
    display: block;
    margin-top: 0.3rem;
    color: var(--text-medium);
    font-size: 0.85rem;
}

/* =======================
   Paginação - PADRONIZADO
   ======================= */

.pagination {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    padding: 1.5rem;
    border-top: 1px solid var(--border-light);
}

.pagination-btn {
    width: 40px;
    height: 40px;
    border-radius: 8px;
    border: 1px solid var(--border-light);
    background: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 500;
    transition: all 0.3s;
}

.pagination-btn.active {
    background: var(--secondary);
    color: white;
    border-color: var(--secondary);
}

.pagination-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination-btn:not(.active):not(:disabled):hover {
    background: #f0f2f5;
    border-color: var(--secondary);
}

/* =======================
   Modal - PADRONIZADO
   ======================= */

.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(5px);
    z-index: 1000;
    justify-content: center;
    align-items: center;
}

.modal.active {
    display: flex;
}

.modal-content {
    background: white;
    border-radius: 10px;
    width: 90%;
    max-width: 600px;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-header {
    padding: 1.5rem;
    border-bottom: 1px solid var(--border-light);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.modal-header h3 {
    font-size: 1.4rem;
    color: var(--primary-dark);
    margin: 0;
}

.modal-close {
    background: none;
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    color: var(--text-medium);
    transition: color 0.3s;
}

.modal-close:hover {
    color: var(--accent);
}

.modal-body {
    padding: 1.5rem;
}

.modal-footer {
    padding: 1rem 1.5rem;
    border-top: 1px solid var(--border-light);
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

/* Grid de detalhes no modal */
.detail-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
}

.detail-item {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.detail-item.full-width {
    grid-column: 1 / -1;
}

.detail-item label {
    font-weight: 600;
    color: var(--primary-dark);
    font-size: 0.9rem;
}

.detail-item span,
.detail-item p {
    color: var(--text-medium);
    margin: 0;
}

.detail-item p {
    line-height: 1.5;
}

/* =======================
   Botões - PADRONIZADO
   ======================= */

.btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    border: none;
    font-size: 0.95rem;
}

.btn-primary {
    background: var(--secondary);
    color: white;
}

.btn-primary:hover {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.btn-secondary {
    background: #f0f2f5;
    color: var(--text-dark);
}

.btn-secondary:hover {
    background: #e6e9f0;
}

/* =======================
   Sistema de Alertas Customizado
   ======================= */

.alert-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(5px);
    z-index: 2000;
    justify-content: center;
    align-items: center;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.alert-overlay.visible {
    display: flex;
    opacity: 1;
}

.alert-modal {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    max-width: 500px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    text-align: center;
    animation: slideDown 0.3s ease;
}

@keyframes slideDown {
    from {
        transform: translateY(-50px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

.alert-icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.alert-overlay.alert-success .alert-icon {
    color: #4CAF50;
}

.alert-overlay.alert-error .alert-icon {
    color: #F44336;
}

.alert-overlay.alert-warning .alert-icon {
    color: #FF9800;
}

.alert-overlay.alert-info .alert-icon {
    color: #2196F3;
}

.alert-title {
    font-size: 1.5rem;
    color: var(--primary-dark);
    margin-bottom: 1rem;
}

.alert-message {
    color: var(--text-medium);
    margin-bottom: 1.5rem;
    line-height: 1.6;
}

.alert-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.alert-btn {
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s;
    border: none;
    font-size: 0.95rem;
    min-width: 120px;
}

.alert-btn-primary {
    background: var(--secondary);
    color: white;
}

.alert-btn-primary:hover {
    background: var(--accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(122, 4, 235, 0.3);
}

.alert-btn-secondary {
    background: #f0f2f5;
    color: var(--text-dark);
}

.alert-btn-secondary:hover {
    background: #e6e9f0;
}

/* =======================
   Responsividade - OTIMIZADA
   ======================= */

@media (max-width: 1200px) {
    .filters-container {
        gap: 1rem;
    }

    .search-box {
        min-width: 250px;
    }

    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 992px) {
    .page-header h1 {
        font-size: clamp(1.5rem, 4vw, 2rem);
    }

    .filters-container {
        flex-direction: column;
        align-items: stretch;
    }

    .filter-group {
        width: 100%;
        justify-content: space-between;
    }

    .search-box {
        min-width: auto;
        flex: 1;
    }

    .filters-container select {
        min-width: 150px;
        flex: 1;
    }
}

@media (max-width: 768px) {
    .admin-content {
        padding: 1rem;
    }

    .filters-section {
        padding: 1.25rem;
    }

    .filter-group {
        flex-direction: column;
        gap: 0.75rem;
    }

    .search-box,
    .filters-container select {
        width: 100%;
        min-width: auto;
    }

    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 0.75rem;
    }

    .stat-card {
        padding: 0.875rem;
        gap: 0.75rem;
    }

    .stat-icon {
        width: 40px;
        height: 40px;
        font-size: 1.1rem;
    }

    .stat-info h3 {
        font-size: 1.3rem;
    }

    .stat-info p {
        font-size: 0.85rem;
    }

    .table-header {
        flex-direction: column;
        gap: 1rem;
        align-items: flex-start;
        padding: 1.25rem;
    }

    .table-actions {
        width: 100%;
        justify-content: flex-end;
    }

    .users-table {
        font-size: 0.85rem;
    }

    .users-table th,
    .users-table td {
        padding: 0.75rem 0.5rem;
        white-space: nowrap;
    }

    .users-table th:nth-child(3), /* Email */
    .users-table td:nth-child(3),
    .users-table th:nth-child(6), /* Data Cadastro */
    .users-table td:nth-child(6) {
        max-width: 120px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .status-badge,
    .role-badge {
        font-size: 0.75rem;
        padding: 0.3rem 0.6rem;
    }

    .actions-cell {
        flex-direction: row;
        gap: 0.3rem;
    }

    .btn-table {
        width: 35px;
        height: 35px;
        font-size: 0.8rem;
    }

    .modal-content {
        width: 95%;
        margin: 1rem;
        max-width: none;
    }

    .detail-grid {
        grid-template-columns: 1fr;
        gap: 0.75rem;
    }

    .detail-item {
        gap: 0.3rem;
    }

    .detail-item label {
        font-size: 0.85rem;
    }

    .detail-item span,
    .detail-item p {
