    }

    /* Formulário responsivo */
    .form-row {
        flex-direction: column;
        gap: 0;
        margin-bottom: 1rem;
    }

    .form-group {
        margin-bottom: 1.25rem;
    }

    .form-group input,
    .form-group select {
        padding: 0.75rem;
        font-size: 16px; /* Previne zoom no iOS */
    }
}

@media (max-width: 576px) {
    .filters-section {
        padding: 1rem;
        border-radius: 8px;
    }

    .stats-cards {
        grid-template-columns: 1fr;
    }

    .stat-card {
        flex-direction: row;
        text-align: left;
        justify-content: flex-start;
    }

    .table-header h3 {
        font-size: 1.1rem;
    }

    .btn {
        padding: 0.7rem 1rem;
        font-size: 0.9rem;
    }

    /* Otimização da tabela para mobile */
    .users-table {
        min-width: 700px; /* Força scroll horizontal */
    }

    .users-table thead th:nth-child(3), /* Email */
    .users-table thead th:nth-child(6), /* Data Cadastro */
