    }

    .stat-card {
        padding: 0.75rem;
    }

    .stat-icon {
        width: 35px;
        height: 35px;
        font-size: 1rem;
    }

    .stat-info h3 {
        font-size: 1.2rem;
    }

    .users-table {
        min-width: 550px;
        font-size: 0.8rem;
    }

    .pagination-btn {
        width: 32px;
        height: 32px;
        font-size: 0.8rem;
    }

    .modal-body {
        padding: 0.875rem;
    }
}

/* =======================
   Melhorias de Usabilidade Mobile
   ======================= */

/* Scroll horizontal suave para a tabela */
.table-responsive {
    -webkit-overflow-scrolling: touch;
    scroll-behavior: smooth;
}

/* Indicador visual de scroll horizontal */
.table-responsive::-webkit-scrollbar {
    height: 6px;
}

.table-responsive::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 3px;
}

.table-responsive::-webkit-scrollbar-thumb {
    background: var(--secondary);
    border-radius: 3px;
}

.table-responsive::-webkit-scrollbar-thumb:hover {
    background: var(--accent);
}

/* Touch-friendly para botões de ação */
.btn-table {
    min-height: 44px;
    min-width: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Feedback visual para toques */
.btn-table:active {
    transform: scale(0.95);
}

/* Loading overlay mobile */
@media (max-width: 768px) {
    #loading-overlay .spinner {
        width: 40px;
        height: 40px;
        border-width: 3px;
    }
}

/* Melhorias para formulário em mobile */
@media (max-width: 768px) {
    .form-group input:focus,
    .form-group select:focus {
        border-width: 2px;
    }

    /* Labels mais claros para mobile */
    .form-group label {
        font-size: 0.9rem;
        margin-bottom: 0.4rem;
    }
}

/* Estados de validação do formulário em mobile */
@media (max-width: 768px) {
    .form-group input:invalid:not(:focus):not(:placeholder-shown) {
        border-color: #F44336;
        background-color: rgba(244, 67, 54, 0.05);
    }

    .form-group input:valid:not(:focus):not(:placeholder-shown) {
        border-color: #4CAF50;
        background-color: rgba(76, 175, 80, 0.05);
    }
}

/* =======================
   High Contrast Mode Mobile
   ======================= */
@media (max-width: 768px) and (prefers-contrast: high) {
    .users-table {
        border: 2px solid #000;
    }

    .users-table th {
        background: #000;
        color: #fff;
    }

    .table-responsive::-webkit-scrollbar-thumb {
        background: #000;
    }

    .form-group input,
    .form-group select {
        border: 2px solid #000;
    }
}

/* =======================
   Reduced Motion Support
   ======================= */
@media (prefers-reduced-motion: reduce) {
    .table-responsive {
        scroll-behavior: auto;
    }

    .btn-table,
    .stat-card,
    .action-card {
        transition: none;
    }

    .btn-table:hover,
    .stat-card:hover {
        transform: none;
    }

    .alert-modal {
        animation: none;
    }
}

/* =======================
   Estado Vazio Melhorado para Mobile
   ======================= */
@media (max-width: 768px) {
    .users-table tbody td[colspan] {
        padding: 2rem 1rem;
        text-align: center;
    }

    .users-table tbody td[colspan] i {
        font-size: 1.5rem;
        margin-bottom: 0.5rem;
    }
}

/* =======================
   Indicador de Scroll para Tabela Mobile
   ======================= */
.scroll-indicator {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    background: var(--secondary);
    color: white;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
    opacity: 0.7;
    animation: bounce 2s infinite;
    z-index: 2;
    pointer-events: none;
}

@keyframes bounce {
    0%, 20%, 50%, 80%, 100% { transform: translateY(-50%) translateX(0); }
    40% { transform: translateY(-50%) translateX(-5px); }
    60% { transform: translateY(-50%) translateX(-3px); }
}

@media (max-width: 576px) {
    .table-responsive {
        position: relative;
        border-radius: 8px;
        box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    }
}

